// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Test suite for strncasecmp() from lib/string.c.
 */

#include <kunit/test.h>
#include <linux/string.h>
#include <linux/ctype.h>

/* Identical strings compare equal regardless of len. */
static void strncasecmp_identical_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("hello", "hello", 5), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("hello", "hello", 100), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("hello", "hello", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("", "", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("", "", 100), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "a", 1), 0);
}

/* Strings differing only in ASCII case compare equal. */
static void strncasecmp_case_insensitive_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("hello", "HELLO", 5), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("HeLLo", "hElLO", 5), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("hello", "HELLO", 50), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "A", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("A", "a", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("z", "Z", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abcdefghijklmnopqrstuvwxyz",
					  "ABCDEFGHIJKLMNOPQRSTUVWXYZ", 26), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("ABCDEFGHIJKLMNOPQRSTUVWXYZ",
					  "abcdefghijklmnopqrstuvwxyz", 100), 0);
	/* Non-letters are unaffected by case folding. */
	KUNIT_EXPECT_EQ(test, strncasecmp("123-_. !", "123-_. !", 8), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("Mixed123Case", "mIXED123cASE", 12), 0);
}

/* Different strings: sign of result reflects lower-cased ordering. */
static void strncasecmp_different_test(struct kunit *test)
{
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "abd", 3), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("abd", "abc", 3), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("ABC", "abd", 3), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("ABD", "abc", 3), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "ABD", 3), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("abd", "ABC", 3), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("a", "b", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("b", "a", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("A", "b", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("B", "a", 1), 0);
	/* Difference in first char dominates even if rest is equal. */
	KUNIT_EXPECT_LT(test, strncasecmp("axyz", "bxyz", 4), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("bxyz", "AXYZ", 4), 0);
}

/* Exact value of the result: difference of the lower-cased chars. */
static void strncasecmp_return_value_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "c", 1), 'a' - 'c');
	KUNIT_EXPECT_EQ(test, strncasecmp("c", "a", 1), 'c' - 'a');
	KUNIT_EXPECT_EQ(test, strncasecmp("A", "c", 1), 'a' - 'c');
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "C", 1), 'a' - 'c');
	KUNIT_EXPECT_EQ(test, strncasecmp("A", "C", 1), 'a' - 'c');
	KUNIT_EXPECT_EQ(test, strncasecmp("xxA", "xxz", 3), 'a' - 'z');
	KUNIT_EXPECT_EQ(test, strncasecmp("1", "9", 1), '1' - '9');
	/* Case-only difference followed by real difference. */
	KUNIT_EXPECT_EQ(test, strncasecmp("Ab", "aC", 2), 'b' - 'c');
}

/* Zero length always compares equal, regardless of contents. */
static void strncasecmp_zero_len_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "xyz", 0), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "b", 0), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("", "nonempty", 0), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("nonempty", "", 0), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("", "", 0), 0);
}

/* Only the first len characters are compared (off-by-one checks). */
static void strncasecmp_prefix_limit_test(struct kunit *test)
{
	/* Differ at index 3 (0-based). */
	KUNIT_EXPECT_EQ(test, strncasecmp("abcX", "abcY", 3), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abcX", "ABCY", 3), 0);
	KUNIT_EXPECT_NE(test, strncasecmp("abcX", "abcY", 4), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("abcX", "abcY", 4), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("abcY", "abcX", 4), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("abcX", "abcY", 5), 0);

	/* Differ at index 0. */
	KUNIT_EXPECT_NE(test, strncasecmp("Xabc", "Yabc", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("Xabc", "Yabc", 0), 0);

	/* Same prefix, one longer: differ at index 5 (where s1 ends). */
	KUNIT_EXPECT_EQ(test, strncasecmp("hello", "hello world", 5), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("HELLO", "hello world", 5), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("hello", "hello world", 6), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("hello world", "hello", 6), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("hello", "HELLO WORLD", 11), 0);

	/* Last-position mismatch only visible at exactly len. */
	KUNIT_EXPECT_EQ(test, strncasecmp("abcdefg", "abcdefh", 6), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("abcdefg", "abcdefh", 7), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("ABCDEFG", "abcdefH", 6), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("ABCDEFG", "abcdefH", 7), 0);
}

/* Memory past len must never be read. */
static void strncasecmp_no_overread_test(struct kunit *test)
{
	char *a, *b;

	a = kunit_kzalloc(test, 8, GFP_KERNEL);
	b = kunit_kzalloc(test, 8, GFP_KERNEL);
	KUNIT_ASSERT_NOT_ERR_OR_NULL(test, a);
	KUNIT_ASSERT_NOT_ERR_OR_NULL(test, b);

	/* No NUL within the first 4 bytes; byte 4 differs. */
	memcpy(a, "ABCDxxx", 7);
	memcpy(b, "abcdyyy", 7);
	KUNIT_EXPECT_EQ(test, strncasecmp(a, b, 4), 0);
	KUNIT_EXPECT_LT(test, strncasecmp(a, b, 5), 0);
	KUNIT_EXPECT_GT(test, strncasecmp(b, a, 5), 0);

	/* Non-terminated buffers, fully equal within len. */
	memset(a, 'Q', 8);
	memset(b, 'q', 8);
	KUNIT_EXPECT_EQ(test, strncasecmp(a, b, 8), 0);
	b[7] = 'r';
	KUNIT_EXPECT_EQ(test, strncasecmp(a, b, 7), 0);
	KUNIT_EXPECT_LT(test, strncasecmp(a, b, 8), 0);
}

/* Behaviour when one or both strings terminate early. */
static void strncasecmp_nul_termination_test(struct kunit *test)
{
	/* Empty vs non-empty: result is 0 - first char or first char - 0. */
	KUNIT_EXPECT_LT(test, strncasecmp("", "a", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("a", "", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("", "a", 5), -'a');
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "", 5), 'a');
	KUNIT_EXPECT_EQ(test, strncasecmp("", "A", 5), -'A');
	KUNIT_EXPECT_EQ(test, strncasecmp("A", "", 5), 'A');

	/* Prefix relationship. */
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "abcd", 10), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("abcd", "abc", 10), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "abcd", 10), -'d');
	KUNIT_EXPECT_EQ(test, strncasecmp("ABCD", "abc", 10), 'D');
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "ABCD", 3), 0);

	/* Embedded NUL stops comparison before len. */
	KUNIT_EXPECT_EQ(test, strncasecmp("ab\0cd", "AB\0xy", 5), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("ab\0cd", "ab\0xy", 5), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("ab\0cd", "abc", 5), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("abc", "ab\0cd", 5), 0);
}

/* High-bit (non-ASCII) bytes must be treated as unsigned. */
static void strncasecmp_unsigned_chars_test(struct kunit *test)
{
	const char hi1[] = { (char)0xff, '\0' };
	const char hi2[] = { (char)0x80, '\0' };
	const char hi3[] = { (char)0xc1, '\0' }; /* 0xc1 is not 'A' */

	/* Bytes >= 0x80 sort above every ASCII byte. */
	KUNIT_EXPECT_GT(test, strncasecmp(hi1, "a", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp(hi2, "a", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("a", hi1, 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("z", hi2, 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp(hi1, hi2, 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp(hi2, hi1, 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp(hi1, hi1, 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp(hi1, hi2, 1), 0xff - 0x80);
	KUNIT_EXPECT_EQ(test, strncasecmp(hi2, hi1, 1), 0x80 - 0xff);

	/* No case folding of high bytes. */
	KUNIT_EXPECT_NE(test, strncasecmp(hi3, "A", 1), 0);
	KUNIT_EXPECT_NE(test, strncasecmp(hi3, "a", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp(hi3, "a", 1), 0);
}

/* Characters neighbouring the letter ranges must not be case-folded. */
static void strncasecmp_non_alpha_boundary_test(struct kunit *test)
{
	/* '@' (0x40) is just before 'A'; '[' (0x5b) is just after 'Z'. */
	KUNIT_EXPECT_NE(test, strncasecmp("@", "`", 1), 0);
	KUNIT_EXPECT_NE(test, strncasecmp("[", "{", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("@", "`", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("[", "{", 1), 0);
	/* '_' vs '?' differ by 0x20 as well. */
	KUNIT_EXPECT_NE(test, strncasecmp("?", "_", 1), 0);
	/* Digits and punctuation compare by raw value. */
	KUNIT_EXPECT_LT(test, strncasecmp("0", "9", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("9", "0", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("a1", "A2", 2), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("A2", "a1", 2), 0);
	/* Uppercase letter vs non-letter with same lowercase-folded value. */
	KUNIT_EXPECT_NE(test, strncasecmp("A", "@", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("A", "@", 1), 0);
	/* 'Z' folds to 'z' (0x7a) which sorts above '[' (0x5b). */
	KUNIT_EXPECT_NE(test, strncasecmp("Z", "[", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("Z", "[", 1), 'z' - '[');
}

/* Consistency with strcasecmp and antisymmetry on a set of inputs. */
static void strncasecmp_consistency_test(struct kunit *test)
{
	static const char * const words[] = {
		"", "a", "A", "b", "ab", "AB", "abc", "ABD", "abcd",
		"Hello", "hello", "HELLO", "hell", "help", "world", "WORLD!",
		"123", "12a", "12B",
	};
	int i, j;

	for (i = 0; i < ARRAY_SIZE(words); i++) {
		for (j = 0; j < ARRAY_SIZE(words); j++) {
			int full = strcasecmp(words[i], words[j]);
			int n = strncasecmp(words[i], words[j], 64);
			int rev = strncasecmp(words[j], words[i], 64);

			/* Same sign as strcasecmp with a large len. */
			KUNIT_EXPECT_EQ_MSG(test, (full > 0) - (full < 0),
					    (n > 0) - (n < 0),
					    "\"%s\" vs \"%s\"",
					    words[i], words[j]);
			/* Antisymmetric. */
			KUNIT_EXPECT_EQ_MSG(test, (n > 0) - (n < 0),
					    -((rev > 0) - (rev < 0)),
					    "\"%s\" vs \"%s\"",
					    words[i], words[j]);
			/* Equal iff case-insensitively identical. */
			if (strlen(words[i]) == strlen(words[j])) {
				size_t k;
				bool same = true;

				for (k = 0; k < strlen(words[i]); k++)
					if (tolower(words[i][k]) !=
					    tolower(words[j][k]))
						same = false;
				KUNIT_EXPECT_EQ_MSG(test, n == 0, same,
						    "\"%s\" vs \"%s\"",
						    words[i], words[j]);
			} else {
				KUNIT_EXPECT_NE_MSG(test, n, 0,
						    "\"%s\" vs \"%s\"",
						    words[i], words[j]);
			}
		}
	}
}

/* Sweep len from 0 past the end of a long pair of strings. */
static void strncasecmp_len_sweep_test(struct kunit *test)
{
	const char *s1 = "The Quick Brown Fox Jumps";
	const char *s2 = "the quick brown fox jumpS";
	/* s3 differs from s1 at index 10 ('B' vs 'C'). */
	const char *s3 = "the quick Crown fox jumps";
	size_t len;

	for (len = 0; len <= 40; len++) {
		KUNIT_EXPECT_EQ_MSG(test, strncasecmp(s1, s2, len), 0,
				    "len=%zu", len);
		if (len <= 10) {
			KUNIT_EXPECT_EQ_MSG(test, strncasecmp(s1, s3, len), 0,
					    "len=%zu", len);
		} else {
			KUNIT_EXPECT_EQ_MSG(test, strncasecmp(s1, s3, len),
					    'b' - 'c', "len=%zu", len);
			KUNIT_EXPECT_EQ_MSG(test, strncasecmp(s3, s1, len),
					    'c' - 'b', "len=%zu", len);
		}
	}
}

/* Very large len values behave like "unbounded". */
static void strncasecmp_huge_len_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("Foo", "fOO", SIZE_MAX), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("Foo", "fOP", SIZE_MAX), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("foobar", "FOO", SIZE_MAX), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("", "", SIZE_MAX), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("x", "", SIZE_MAX), 'x');
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(strncasecmp_identical_test),
	KUNIT_CASE(strncasecmp_case_insensitive_test),
	KUNIT_CASE(strncasecmp_different_test),
	KUNIT_CASE(strncasecmp_return_value_test),
	KUNIT_CASE(strncasecmp_zero_len_test),
	KUNIT_CASE(strncasecmp_prefix_limit_test),
	KUNIT_CASE(strncasecmp_no_overread_test),
	KUNIT_CASE(strncasecmp_nul_termination_test),
	KUNIT_CASE(strncasecmp_unsigned_chars_test),
	KUNIT_CASE(strncasecmp_non_alpha_boundary_test),
	KUNIT_CASE(strncasecmp_consistency_test),
	KUNIT_CASE(strncasecmp_len_sweep_test),
	KUNIT_CASE(strncasecmp_huge_len_test),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};

kunit_test_suite(agent_test_suite);

MODULE_DESCRIPTION("KUnit test for strncasecmp()");
MODULE_LICENSE("GPL");

// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Test suite for strcspn() from lib/string.c.
 */

#include <kunit/test.h>
#include <linux/string.h>

/* Normal input: first reject char in the middle of the string. */
static void strcspn_basic_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("hello world", " "), 5);
	KUNIT_EXPECT_EQ(test, strcspn("hello world", "ow"), 4);
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "fed"), 3);
	KUNIT_EXPECT_EQ(test, strcspn("key=value", "="), 3);
}

/* Empty string: always 0 regardless of reject set. */
static void strcspn_empty_string_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("", ""), 0);
	KUNIT_EXPECT_EQ(test, strcspn("", "abc"), 0);
}

/* Empty reject set: span is the whole string. */
static void strcspn_empty_reject_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("a", ""), 1);
	KUNIT_EXPECT_EQ(test, strcspn("hello", ""), 5);
	KUNIT_EXPECT_EQ(test, strcspn("hello", ""), strlen("hello"));
}

/* No rejected char present: span is the whole string. */
static void strcspn_no_match_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("hello", "xyz"), 5);
	KUNIT_EXPECT_EQ(test, strcspn("abc", "d"), 3);
	KUNIT_EXPECT_EQ(test, strcspn("a", "b"), 1);
}

/* Rejected char at index 0: span is 0. */
static void strcspn_match_first_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("hello", "h"), 0);
	KUNIT_EXPECT_EQ(test, strcspn("hello", "zyh"), 0);
	KUNIT_EXPECT_EQ(test, strcspn("a", "a"), 0);
	KUNIT_EXPECT_EQ(test, strcspn(" x", " "), 0);
}

/* Rejected char is the last char: span is len-1. */
static void strcspn_match_last_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("hello", "o"), 4);
	KUNIT_EXPECT_EQ(test, strcspn("ab", "b"), 1);
	KUNIT_EXPECT_EQ(test, strcspn("abc", "c"), 2);
}

/* Multiple matches: only the first one counts. */
static void strcspn_first_occurrence_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("banana", "n"), 2);
	KUNIT_EXPECT_EQ(test, strcspn("banana", "a"), 1);
	KUNIT_EXPECT_EQ(test, strcspn("aaaa", "a"), 0);
	KUNIT_EXPECT_EQ(test, strcspn("a,b,c", ",;"), 1);
	KUNIT_EXPECT_EQ(test, strcspn("a;b,c", ",;"), 1);
}

/* Single-char string in both directions. */
static void strcspn_single_char_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("x", "x"), 0);
	KUNIT_EXPECT_EQ(test, strcspn("x", "y"), 1);
	KUNIT_EXPECT_EQ(test, strcspn("x", ""), 1);
}

/*
 * The NUL terminator of reject must never be treated as a member of
 * the reject set; otherwise the terminator of s would be "matched"
 * (fine) but, more importantly, strchr(reject, c) with c != '\0'
 * must not match the terminator. Also s must stop at its own NUL
 * even when reject is empty (strchr("", '\0') is non-NULL).
 */
static void strcspn_nul_handling_test(struct kunit *test)
{
	/* Embedded NUL terminates s; chars after it must be ignored. */
	static const char s[] = "abc\0xyz";

	KUNIT_EXPECT_EQ(test, strcspn(s, "x"), 3);
	KUNIT_EXPECT_EQ(test, strcspn(s, "z"), 3);
	KUNIT_EXPECT_EQ(test, strcspn(s, ""), 3);
	/* Chars beyond the reject terminator must be ignored. */
	{
		static const char r[] = "q\0a";

		KUNIT_EXPECT_EQ(test, strcspn("abc", r), 3);
	}
}

/* Reject set containing duplicates and the full ASCII range. */
static void strcspn_reject_variants_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("hello", "lll"), 2);
	KUNIT_EXPECT_EQ(test, strcspn("hello", "ol"), 2);
	KUNIT_EXPECT_EQ(test, strcspn("hello", "lo"), 2);
	/* Case sensitivity. */
	KUNIT_EXPECT_EQ(test, strcspn("Hello", "h"), 5);
	KUNIT_EXPECT_EQ(test, strcspn("Hello", "H"), 0);
	KUNIT_EXPECT_EQ(test, strcspn("abcABC", "A"), 3);
}

/* High-bit (non-ASCII) bytes must compare correctly (no sign issues). */
static void strcspn_high_bytes_test(struct kunit *test)
{
	static const char s[] = { 'a', 'b', (char)0xff, 'c', '\0' };
	static const char r_ff[] = { (char)0xff, '\0' };
	static const char r_80[] = { (char)0x80, '\0' };
	static const char s80[] = { (char)0x80, 'z', '\0' };

	KUNIT_EXPECT_EQ(test, strcspn(s, r_ff), 2);
	KUNIT_EXPECT_EQ(test, strcspn(s, r_80), 4);
	KUNIT_EXPECT_EQ(test, strcspn(s80, r_80), 0);
	KUNIT_EXPECT_EQ(test, strcspn(s80, "z"), 1);
	KUNIT_EXPECT_EQ(test, strcspn(s80, r_ff), 2);
}

/* Return value is the prefix length: s[ret] is in reject or is NUL. */
static void strcspn_postcondition_test(struct kunit *test)
{
	static const char *const strs[] = {
		"", "a", "abc", "hello world", "x=y;z", "\t\n ", "zzzz",
	};
	static const char *const rejs[] = {
		"", "a", "z", " ", "=;", "\n", "abcdefghijklmnopqrstuvwxyz",
	};
	int i, j;

	for (i = 0; i < ARRAY_SIZE(strs); i++) {
		for (j = 0; j < ARRAY_SIZE(rejs); j++) {
			const char *s = strs[i];
			const char *r = rejs[j];
			size_t ret = strcspn(s, r);
			size_t k;

			KUNIT_EXPECT_LE_MSG(test, ret, strlen(s),
					    "s=\"%s\" r=\"%s\"", s, r);
			/* No prefix char is in reject. */
			for (k = 0; k < ret; k++)
				KUNIT_EXPECT_NULL_MSG(test, strchr(r, s[k]),
						      "s=\"%s\" r=\"%s\" k=%zu",
						      s, r, k);
			/* Terminating char is rejected or end of string. */
			if (s[ret] != '\0')
				KUNIT_EXPECT_NOT_NULL_MSG(test, strchr(r, s[ret]),
							  "s=\"%s\" r=\"%s\"",
							  s, r);
		}
	}
}

/* Long string; match far past small-buffer sizes, and at exact end. */
static void strcspn_long_string_test(struct kunit *test)
{
	char *buf;
	const size_t len = 1000;

	buf = kunit_kzalloc(test, len + 1, GFP_KERNEL);
	KUNIT_ASSERT_NOT_ERR_OR_NULL(test, buf);
	memset(buf, 'a', len);
	buf[len] = '\0';

	KUNIT_EXPECT_EQ(test, strcspn(buf, "b"), len);
	KUNIT_EXPECT_EQ(test, strcspn(buf, ""), len);
	KUNIT_EXPECT_EQ(test, strcspn(buf, "a"), 0);

	buf[len - 1] = 'b';
	KUNIT_EXPECT_EQ(test, strcspn(buf, "b"), len - 1);

	buf[500] = 'c';
	KUNIT_EXPECT_EQ(test, strcspn(buf, "c"), 500);
	KUNIT_EXPECT_EQ(test, strcspn(buf, "bc"), 500);
	KUNIT_EXPECT_EQ(test, strcspn(buf, "b"), len - 1);
}

/* Agreement with strpbrk, which has the same search semantics. */
static void strcspn_vs_strpbrk_test(struct kunit *test)
{
	static const char *const strs[] = {
		"hello world", "banana", "abc", "", "a", "/usr/lib/x",
	};
	static const char *const rejs[] = { " ", "n", "c", "", "/", "q" };
	int i, j;

	for (i = 0; i < ARRAY_SIZE(strs); i++) {
		for (j = 0; j < ARRAY_SIZE(rejs); j++) {
			const char *s = strs[i];
			const char *r = rejs[j];
			const char *p = strpbrk(s, r);
			size_t expected = p ? (size_t)(p - s) : strlen(s);

			KUNIT_EXPECT_EQ_MSG(test, strcspn(s, r), expected,
					    "s=\"%s\" r=\"%s\"", s, r);
		}
	}
}

