#include <kunit/test.h>
#include <linux/string.h>
#include <linux/string_helpers.h>
#include <linux/limits.h>

#define BUFLEN 32

struct gs_case {
	u64 size;
	u64 blk_size;
	const char *exp10;
	const char *exp2;
};

static void check_one(struct kunit *test, u64 size, u64 blk_size,
		      enum string_size_units units, const char *exp)
{
	char buf[BUFLEN];
	int ret;

	memset(buf, 'X', sizeof(buf));
	ret = string_get_size(size, blk_size, units, buf, sizeof(buf));

	KUNIT_EXPECT_STREQ_MSG(test, buf, exp,
			       "string_get_size(%llu, %llu, 0x%x)",
			       size, blk_size, (unsigned int)units);
	KUNIT_EXPECT_EQ_MSG(test, ret, (int)strlen(exp),
			    "return value for string_get_size(%llu, %llu, 0x%x)",
			    size, blk_size, (unsigned int)units);
}

static void check_table(struct kunit *test, const struct gs_case *tbl, size_t n)
{
	size_t i;

	for (i = 0; i < n; i++) {
		check_one(test, tbl[i].size, tbl[i].blk_size,
			  STRING_UNITS_10, tbl[i].exp10);
		check_one(test, tbl[i].size, tbl[i].blk_size,
			  STRING_UNITS_2, tbl[i].exp2);
	}
}

#define CHECK_TABLE(test, tbl) check_table(test, tbl, ARRAY_SIZE(tbl))

/* size == 0 or blk_size == 0 always yields "0 B" regardless of units. */
static void agent_zero(struct kunit *test)
{
	static const struct gs_case tbl[] = {
		{ 0, 0, "0 B", "0 B" },
		{ 0, 1, "0 B", "0 B" },
		{ 0, 512, "0 B", "0 B" },
		{ 1, 0, "0 B", "0 B" },
		{ 512, 0, "0 B", "0 B" },
		{ U64_MAX, 0, "0 B", "0 B" },
		{ 0, U64_MAX, "0 B", "0 B" },
	};

	CHECK_TABLE(test, tbl);

	/* zero with flags */
	check_one(test, 0, 1, STRING_UNITS_10 | STRING_UNITS_NO_SPACE, "0B");
	check_one(test, 0, 1, STRING_UNITS_2 | STRING_UNITS_NO_BYTES, "0 ");
	check_one(test, 0, 1, STRING_UNITS_10 | STRING_UNITS_NO_SPACE |
		  STRING_UNITS_NO_BYTES, "0");
}

/* Values below the first divisor: unit is bare "B". */
static void agent_bytes(struct kunit *test)
{
	static const struct gs_case tbl[] = {
		/* 3-significant-figure padding applies even to bytes */
		{ 1, 1, "1.00 B", "1.00 B" },
		{ 9, 1, "9.00 B", "9.00 B" },
		{ 10, 1, "10.0 B", "10.0 B" },
		{ 99, 1, "99.0 B", "99.0 B" },
		{ 100, 1, "100 B", "100 B" },
		{ 512, 1, "512 B", "512 B" },
		{ 1, 512, "512 B", "512 B" },
		{ 999, 1, "999 B", "999 B" },
		/* 1000..1023: kB in SI, still bytes in binary */
		{ 1000, 1, "1.00 kB", "1000 B" },
		{ 1001, 1, "1.00 kB", "1001 B" },
		{ 1023, 1, "1.02 kB", "1023 B" },
		{ 1024, 1, "1.02 kB", "1.00 KiB" },
		{ 1025, 1, "1.03 kB", "1.00 KiB" },
	};

	CHECK_TABLE(test, tbl);
}

/* Decimal digits and rounding behaviour. */
static void agent_rounding(struct kunit *test)
{
	static const struct gs_case tbl[] = {
		{ 1100, 1, "1.10 kB", "1.07 KiB" },
		{ 1500, 1, "1.50 kB", "1.46 KiB" },
		{ 1536, 1, "1.54 kB", "1.50 KiB" },
		{ 10000, 1, "10.0 kB", "9.77 KiB" },
		/* two decimals: remainder 4 rounds down, 5 rounds up */
		{ 1004, 1, "1.00 kB", "1004 B" },
		{ 1005, 1, "1.01 kB", "1005 B" },
		{ 1014, 1, "1.01 kB", "1014 B" },
		{ 1015, 1, "1.02 kB", "1015 B" },
		/* one decimal: remainder 49 rounds down, 50 rounds up */
		{ 10049, 1, "10.0 kB", "9.81 KiB" },
		{ 10050, 1, "10.1 kB", "9.81 KiB" },
		/* carry from the fraction into the integer part */
		{ 1994, 1, "1.99 kB", "1.95 KiB" },
		{ 1995, 1, "2.00 kB", "1.95 KiB" },
		/* carry at one decimal: 99.95 -> 100.0 (digits fixed first) */
		{ 99949, 1, "99.9 kB", "97.6 KiB" },
		{ 99950, 1, "100.0 kB", "97.6 KiB" },
		/* carry with no decimals: 999.5 kB -> 1000 kB */
		{ 999499, 1, "999 kB", "976 KiB" },
		{ 999500, 1, "1000 kB", "976 KiB" },
		{ 999999, 1, "1000 kB", "977 KiB" },
		{ 1000000, 1, "1.00 MB", "977 KiB" },
		/* binary rounding boundary: 1023/1024 -> 0.999 -> 1.00 */
		{ 2047, 1, "2.05 kB", "2.00 KiB" },
		/* carry never moves to the next unit: 1023.999 KiB -> 1024 KiB */
		{ 1048575, 1, "1.05 MB", "1024 KiB" },
		{ 1048576, 1, "1.05 MB", "1.00 MiB" },
	};

	CHECK_TABLE(test, tbl);
}

