/* Truncation: return value is the untruncated length, buffer is NUL-terminated. */
static void agent_truncation(struct kunit *test)
{
	char buf[BUFLEN];
	int ret;
	int i;

	/* "1.10 kB" is 7 chars */
	memset(buf, 'X', sizeof(buf));
	ret = string_get_size(1100, 1, STRING_UNITS_10, buf, 8);
	KUNIT_EXPECT_EQ(test, ret, 7);
	KUNIT_EXPECT_STREQ(test, buf, "1.10 kB");
	KUNIT_EXPECT_EQ(test, buf[8], 'X');

	memset(buf, 'X', sizeof(buf));
	ret = string_get_size(1100, 1, STRING_UNITS_10, buf, 7);
	KUNIT_EXPECT_EQ(test, ret, 7);
	KUNIT_EXPECT_STREQ(test, buf, "1.10 k");
	KUNIT_EXPECT_EQ(test, buf[7], 'X');

	memset(buf, 'X', sizeof(buf));
	ret = string_get_size(1100, 1, STRING_UNITS_10, buf, 4);
	KUNIT_EXPECT_EQ(test, ret, 7);
	KUNIT_EXPECT_STREQ(test, buf, "1.1");
	KUNIT_EXPECT_EQ(test, buf[4], 'X');

	memset(buf, 'X', sizeof(buf));
	ret = string_get_size(1100, 1, STRING_UNITS_10, buf, 1);
	KUNIT_EXPECT_EQ(test, ret, 7);
	KUNIT_EXPECT_STREQ(test, buf, "");
	KUNIT_EXPECT_EQ(test, buf[1], 'X');

	/* len == 0: nothing written at all */
	memset(buf, 'X', sizeof(buf));
	ret = string_get_size(1100, 1, STRING_UNITS_2, buf, 0);
	KUNIT_EXPECT_EQ(test, ret, 8);	/* "1.07 KiB" */
	for (i = 0; i < BUFLEN; i++)
		KUNIT_EXPECT_EQ(test, buf[i], 'X');

	/* "UNK" output is 9 chars plus NUL, matching the documented minimum */
	memset(buf, 'X', sizeof(buf));
	ret = string_get_size(1000000000000000000ULL, 1000000000ULL,
			      STRING_UNITS_10, buf, sizeof(buf));
	KUNIT_EXPECT_EQ(test, ret, 9);
	KUNIT_EXPECT_STREQ(test, buf, "1.00 UNKB");
	KUNIT_EXPECT_EQ(test, buf[10], 'X');
}

