// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Tests for string_escape_mem() in lib/string_helpers.c.
 */

#include <kunit/test.h>
#include <linux/string.h>
#include <linux/string_helpers.h>

#define GUARD	0xA5
#define BUFSZ	256

/*
 * Run string_escape_mem() with a guarded destination buffer and check:
 *  - the return value equals the full escaped length (strlen(exp)),
 *  - exactly min(osz, exp_len) bytes were written and match @exp,
 *  - nothing past @osz was touched.
 */
static void check_escape(struct kunit *test, const char *src, size_t isz,
			 size_t osz, unsigned int flags, const char *only,
			 const char *exp, size_t exp_len)
{
	char dst[BUFSZ];
	size_t written = min(osz, exp_len);
	size_t i;
	int ret;

	KUNIT_ASSERT_LT(test, osz, (size_t)BUFSZ);

	memset(dst, GUARD, sizeof(dst));
	ret = string_escape_mem(src, isz, dst, osz, flags, only);

	KUNIT_EXPECT_EQ_MSG(test, ret, (int)exp_len,
			    "flags=%#x osz=%zu src=%*pE", flags, osz, (int)isz, src);
	KUNIT_EXPECT_MEMEQ_MSG(test, dst, exp, written,
			       "flags=%#x osz=%zu src=%*pE", flags, osz, (int)isz, src);
	for (i = written; i < sizeof(dst); i++) {
		KUNIT_EXPECT_EQ_MSG(test, (unsigned char)dst[i], (unsigned char)GUARD,
				    "byte %zu clobbered (osz=%zu, exp_len=%zu)",
				    i, osz, exp_len);
		if ((unsigned char)dst[i] != GUARD)
			break;
	}
}

/* Run with a generous buffer, and with all truncation points 0..exp_len+1. */
static void check_escape_all(struct kunit *test, const char *src, size_t isz,
			     unsigned int flags, const char *only,
			     const char *exp, size_t exp_len)
{
	size_t osz;

	check_escape(test, src, isz, BUFSZ - 1, flags, only, exp, exp_len);
	for (osz = 0; osz <= exp_len + 1; osz++)
		check_escape(test, src, isz, osz, flags, only, exp, exp_len);
}

/* @src and @exp are string literals; embedded NULs are handled. */
#define CHECK(src, flags, only, exp) \
	check_escape_all(test, src, sizeof(src) - 1, flags, only, exp, \
			 sizeof(exp) - 1)
/* Like CHECK but consumes exactly @isz bytes of @src. */
#define CHECKN(src, isz, flags, only, exp) \
	check_escape_all(test, src, isz, flags, only, exp, sizeof(exp) - 1)

/* ---- normal inputs ---------------------------------------------------- */

static void agent_passthrough_no_flags(struct kunit *test)
{
	/* flags == 0: everything, including control bytes and NUL, passes through */
	CHECK("abc", 0, NULL, "abc");
	CHECK("\n\t\\\"\a\e", 0, NULL, "\n\t\\\"\a\e");
	CHECKN("a\0b", 3, 0, NULL, "a\0b");
	check_escape(test, "a\0b", 3, 10, 0, NULL, "a\0b", 3);
}

static void agent_escape_space(struct kunit *test)
{
	CHECK("\f\n\r\t\v", ESCAPE_SPACE, NULL, "\\f\\n\\r\\t\\v");
	/* a plain space and other classes are not touched by ESCAPE_SPACE */
	CHECK("a b\\\"\a\e\001", ESCAPE_SPACE, NULL, "a b\\\"\a\e\001");
	CHECK("x\ny", ESCAPE_SPACE, NULL, "x\\ny");
}

static void agent_escape_special(struct kunit *test)
{
	CHECK("\\\a\e\"", ESCAPE_SPECIAL, NULL, "\\\\\\a\\e\\\"");
	/* whitespace, NUL and others untouched */
	CHECKN("\n\t\0 'x", 6, ESCAPE_SPECIAL, NULL, "\n\t\0 'x");
	CHECK("say \"hi\"", ESCAPE_SPECIAL, NULL, "say \\\"hi\\\"");
}

static void agent_escape_null(struct kunit *test)
{
	CHECKN("\0", 1, ESCAPE_NULL, NULL, "\\0");
	CHECKN("a\0b\0", 4, ESCAPE_NULL, NULL, "a\\0b\\0");
	/* '0' is not NUL; \001 is not NUL */
	CHECK("0\001", ESCAPE_NULL, NULL, "0\001");
}

static void agent_escape_octal(struct kunit *test)
{
	/* octal escapes every byte with exactly 3 digits */
	CHECKN("\0", 1, ESCAPE_OCTAL, NULL, "\\000");
	CHECK("\001", ESCAPE_OCTAL, NULL, "\\001");
	CHECK("\007", ESCAPE_OCTAL, NULL, "\\007");
	CHECK("\010", ESCAPE_OCTAL, NULL, "\\010");
	CHECK("\077", ESCAPE_OCTAL, NULL, "\\077");
	CHECK("\100", ESCAPE_OCTAL, NULL, "\\100");
	CHECK("\177", ESCAPE_OCTAL, NULL, "\\177");
	CHECK("\200", ESCAPE_OCTAL, NULL, "\\200");
	CHECK("\377", ESCAPE_OCTAL, NULL, "\\377");
	CHECK("a1", ESCAPE_OCTAL, NULL, "\\141\\061");
}

static void agent_escape_hex(struct kunit *test)
{
	CHECKN("\0", 1, ESCAPE_HEX, NULL, "\\x00");
	CHECK("\x01", ESCAPE_HEX, NULL, "\\x01");
	CHECK("\x0f", ESCAPE_HEX, NULL, "\\x0f");
	CHECK("\x10", ESCAPE_HEX, NULL, "\\x10");
	CHECK("\x7f", ESCAPE_HEX, NULL, "\\x7f");
	CHECK("\x80", ESCAPE_HEX, NULL, "\\x80");
	CHECK("\xab", ESCAPE_HEX, NULL, "\\xab");
	CHECK("\xff", ESCAPE_HEX, NULL, "\\xff");
	CHECK("A", ESCAPE_HEX, NULL, "\\x41");
	CHECK("ab", ESCAPE_HEX, NULL, "\\x61\\x62");
}

static void agent_octal_beats_hex(struct kunit *test)
{
	CHECK("A", ESCAPE_OCTAL | ESCAPE_HEX, NULL, "\\101");
	CHECK("\xff", ESCAPE_OCTAL | ESCAPE_HEX, NULL, "\\377");
}

static void agent_class_priority(struct kunit *test)
{
	/* SPACE, SPECIAL and NULL take precedence over OCTAL/HEX */
	CHECK("\n", ESCAPE_SPACE | ESCAPE_OCTAL, NULL, "\\n");
	CHECK("\n", ESCAPE_SPACE | ESCAPE_HEX, NULL, "\\n");
	CHECK("\\", ESCAPE_SPECIAL | ESCAPE_OCTAL, NULL, "\\\\");
	CHECK("\e", ESCAPE_SPECIAL | ESCAPE_HEX, NULL, "\\e");
	CHECKN("\0", 1, ESCAPE_NULL | ESCAPE_OCTAL, NULL, "\\0");
	CHECKN("\0", 1, ESCAPE_NULL | ESCAPE_HEX, NULL, "\\0");
	/* without the SPACE class, '\n' falls through to octal */
	CHECK("\n", ESCAPE_OCTAL, NULL, "\\012");
	CHECK("\n", ESCAPE_SPECIAL | ESCAPE_OCTAL, NULL, "\\012");
	/* without the NULL class, NUL falls through to octal/hex */
	CHECKN("\0", 1, ESCAPE_SPACE | ESCAPE_SPECIAL | ESCAPE_OCTAL, NULL, "\\000");
}

static void agent_escape_any(struct kunit *test)
{
	/* ESCAPE_ANY = SPACE | SPECIAL | NULL | OCTAL: everything gets escaped */
	CHECKN("a\n\0\\\001", 5, ESCAPE_ANY, NULL, "\\141\\n\\0\\\\\\001");
	CHECK(" ", ESCAPE_ANY, NULL, "\\040");
}

static void agent_escape_np(struct kunit *test)
{
	/* printable characters pass, non-printables are octal escaped */
	CHECK("a ~!", ESCAPE_NP | ESCAPE_OCTAL, NULL, "a ~!");
	CHECKN("\001\037\177\0", 4, ESCAPE_NP | ESCAPE_OCTAL, NULL,
	       "\\001\\037\\177\\000");
	/* boundaries of the printable range: 0x1f/0x20 and 0x7e/0x7f */
	CHECK("\037 ", ESCAPE_NP | ESCAPE_HEX, NULL, "\\x1f ");
	CHECK("~\177", ESCAPE_NP | ESCAPE_HEX, NULL, "~\\x7f");
	/* isprint() in the kernel treats 0xa0..0xff as printable; 0x80..0x9f not */
	CHECK("\x80\x9f", ESCAPE_NP | ESCAPE_HEX, NULL, "\\x80\\x9f");
	CHECK("\xa0\xfe\xff", ESCAPE_NP | ESCAPE_HEX, NULL, "\xa0\xfe\xff");
	/* NP alone (no escaping class) still passes printable, and passes others too */
	CHECK("a\n", ESCAPE_NP, NULL, "a\n");
	/* ESCAPE_ANY_NP: printable pass through even though ESCAPE_ANY covers them */
	CHECKN("a\n\0\\", 4, ESCAPE_ANY_NP, NULL, "a\\n\\0\\");
	/* NP overrides SPECIAL for printable chars like '"' and '\\' */
	CHECK("\"\\", ESCAPE_NP | ESCAPE_SPECIAL, NULL, "\"\\");
}

static void agent_escape_na(struct kunit *test)
{
	/* ASCII (incl. control chars) passes, non-ASCII is escaped */
	CHECK("a\n\001\177", ESCAPE_NA | ESCAPE_HEX, NULL, "a\n\001\177");
	CHECK("\x80\xa0\xff", ESCAPE_NA | ESCAPE_HEX, NULL, "\\x80\\xa0\\xff");
	CHECK("\177\200", ESCAPE_NA | ESCAPE_OCTAL, NULL, "\177\\200");
	/* NA overrides SPACE for ASCII whitespace */
	CHECK("\n", ESCAPE_NA | ESCAPE_SPACE | ESCAPE_HEX, NULL, "\n");
	CHECKN("\0", 1, ESCAPE_NA | ESCAPE_NULL | ESCAPE_HEX, NULL, "\0");
}

static void agent_escape_nap(struct kunit *test)
{
	/* only printable ASCII passes; everything else escaped */
	CHECK("a ~", ESCAPE_NAP | ESCAPE_HEX, NULL, "a ~");
	CHECK("\n\177", ESCAPE_NAP | ESCAPE_HEX, NULL, "\\x0a\\x7f");
	/* 0xa0 is isprint() but not ASCII: must be escaped under NAP */
	CHECK("\xa0\xfe", ESCAPE_NAP | ESCAPE_HEX, NULL, "\\xa0\\xfe");
	CHECK("\x80\xff", ESCAPE_NAP | ESCAPE_OCTAL, NULL, "\\200\\377");
	/* NAP with SPACE/SPECIAL classes applied to non-passing chars */
	CHECK("\n\\\a", ESCAPE_NAP | ESCAPE_SPACE | ESCAPE_SPECIAL | ESCAPE_HEX, NULL,
	      "\\n\\\\a");
	CHECKN("\0\x80", 2, ESCAPE_NAP | ESCAPE_NULL, NULL, "\\0\x80");
}

static void agent_only_dict(struct kunit *test)
{
	/* chars not in @only pass through unescaped, even non-printables */
	CHECK("a\nb\tc", ESCAPE_SPACE, "\n", "a\\nb\tc");
	CHECK("a\nb\tc", ESCAPE_SPACE, "\t", "a\nb\\tc");
	CHECK("a\nb\tc", ESCAPE_SPACE, "\t\n", "a\\nb\\tc");
	/* a char in @only but not in a selected class is copied unescaped */
	CHECK("abc", ESCAPE_SPACE, "b", "abc");
	CHECK("abc", ESCAPE_OCTAL, "b", "a\\142c");
	CHECK("abc", ESCAPE_HEX, "ac", "\\x61b\\x63");
	/* last char of only string matters */
	CHECK("xyz", ESCAPE_HEX, "xz", "\\x78y\\x7a");
	/*
	 * strchr(only, '\0') returns a pointer to the terminator, so a NUL
	 * byte is always considered part of a non-empty dictionary.
	 */
	CHECKN("a\0", 2, ESCAPE_NULL, "z", "a\\0");
	/* ESCAPE_ANY with a dict containing only some characters */
	CHECKN("a\0\n", 3, ESCAPE_ANY, "a", "\\141\\0\n");
}

static void agent_only_empty_is_no_dict(struct kunit *test)
{
	/* empty @only behaves like NULL: no dictionary at all */
	CHECK("a\nb", ESCAPE_SPACE, "", "a\\nb");
	CHECK("ab", ESCAPE_HEX, "", "\\x61\\x62");
	CHECK("ab", ESCAPE_HEX, NULL, "\\x61\\x62");
}

static void agent_only_with_np_na(struct kunit *test)
{
	/* without APPEND, @only restricts: only listed chars may be escaped */
	CHECK("\001\002", ESCAPE_NP | ESCAPE_HEX, "\001", "\\x01\002");
	/* printable chars in @only still pass through under NP */
	CHECK("ab\001", ESCAPE_NP | ESCAPE_HEX, "a\001", "ab\\x01");
	CHECK("\x80\x81", ESCAPE_NA | ESCAPE_HEX, "\x81", "\x80\\x81");
}

static void agent_escape_append(struct kunit *test)
{
	/* APPEND: chars in @only are escaped even if printable/ASCII */
	CHECK("a b", ESCAPE_NP | ESCAPE_APPEND | ESCAPE_HEX, " ", "a\\x20b");
	CHECK("a b", ESCAPE_NA | ESCAPE_APPEND | ESCAPE_OCTAL, " ", "a\\040b");
	CHECK("a b", ESCAPE_NAP | ESCAPE_APPEND | ESCAPE_HEX, "b", "a \\x62");
	/* with APPEND, chars not in @only are still subject to the normal NP rule */
	CHECK("a\001", ESCAPE_NP | ESCAPE_APPEND | ESCAPE_HEX, "a", "\\x61\\x01");
	/* appended char that has no class to escape it passes through */
	CHECK("ab", ESCAPE_NP | ESCAPE_APPEND | ESCAPE_SPACE, "a", "ab");
	/* appended char uses SPACE/SPECIAL classes if applicable */
	CHECK("a\"", ESCAPE_NP | ESCAPE_APPEND | ESCAPE_SPECIAL, "\"", "a\\\"");
	/* APPEND without NP/NA/NAP: every char is subject to the classes */
	CHECK("ab", ESCAPE_APPEND | ESCAPE_HEX, "a", "\\x61\\x62");
	CHECK("ab", ESCAPE_APPEND | ESCAPE_HEX, "", "\\x61\\x62");
	/* APPEND with NULL only: equivalent to no dictionary */
	CHECK("ab", ESCAPE_NP | ESCAPE_APPEND | ESCAPE_HEX, NULL, "ab");
}

/* ---- boundaries and sizes --------------------------------------------- */

static void agent_zero_input(struct kunit *test)
{
	char dst[4];
	int ret;

	memset(dst, GUARD, sizeof(dst));
	ret = string_escape_mem("abc", 0, dst, sizeof(dst), ESCAPE_ANY, NULL);
	KUNIT_EXPECT_EQ(test, ret, 0);
	KUNIT_EXPECT_EQ(test, (unsigned char)dst[0], (unsigned char)GUARD);

	memset(dst, GUARD, sizeof(dst));
	ret = string_escape_mem("abc", 0, dst, 0, ESCAPE_ANY, NULL);
	KUNIT_EXPECT_EQ(test, ret, 0);
	KUNIT_EXPECT_EQ(test, (unsigned char)dst[0], (unsigned char)GUARD);
}

static void agent_zero_output_returns_length(struct kunit *test)
{
	char dst[4];
	int ret;

	memset(dst, GUARD, sizeof(dst));
	ret = string_escape_mem("a\n\0", 3, dst, 0, ESCAPE_ANY, NULL);
	KUNIT_EXPECT_EQ(test, ret, 8); /* \141 \n \0 */
	KUNIT_EXPECT_EQ(test, (unsigned char)dst[0], (unsigned char)GUARD);

	ret = string_escape_mem("abc", 3, dst, 0, 0, NULL);
	KUNIT_EXPECT_EQ(test, ret, 3);
	KUNIT_EXPECT_EQ(test, (unsigned char)dst[0], (unsigned char)GUARD);
}

static void agent_exact_fit(struct kunit *test)
{
	char dst[8];
	int ret;

	memset(dst, GUARD, sizeof(dst));
	ret = string_escape_mem("\xff", 1, dst, 4, ESCAPE_HEX, NULL);
	KUNIT_EXPECT_EQ(test, ret, 4);
	KUNIT_EXPECT_MEMEQ(test, dst, "\\xff", 4);
	KUNIT_EXPECT_EQ(test, (unsigned char)dst[4], (unsigned char)GUARD);

	memset(dst, GUARD, sizeof(dst));
	ret = string_escape_mem("ab", 2, dst, 2, 0, NULL);
	KUNIT_EXPECT_EQ(test, ret, 2);
	KUNIT_EXPECT_MEMEQ(test, dst, "ab", 2);
	KUNIT_EXPECT_EQ(test, (unsigned char)dst[2], (unsigned char)GUARD);
}

static void agent_truncation_mid_escape(struct kunit *test)
{
	char dst[8];
	int ret;

	/* octal: 4-byte escape with 1, 2, 3 bytes of room */
	memset(dst, GUARD, sizeof(dst));
	ret = string_escape_mem("\xff", 1, dst, 1, ESCAPE_OCTAL, NULL);
	KUNIT_EXPECT_EQ(test, ret, 4);
	KUNIT_EXPECT_EQ(test, dst[0], '\\');
	KUNIT_EXPECT_EQ(test, (unsigned char)dst[1], (unsigned char)GUARD);

	memset(dst, GUARD, sizeof(dst));
	ret = string_escape_mem("\xff", 1, dst, 2, ESCAPE_OCTAL, NULL);
	KUNIT_EXPECT_EQ(test, ret, 4);
	KUNIT_EXPECT_MEMEQ(test, dst, "\\3", 2);
	KUNIT_EXPECT_EQ(test, (unsigned char)dst[2], (unsigned char)GUARD);

	memset(dst, GUARD, sizeof(dst));
	ret = string_escape_mem("\xff", 1, dst, 3, ESCAPE_OCTAL, NULL);
	KUNIT_EXPECT_EQ(test, ret, 4);
	KUNIT_EXPECT_MEMEQ(test, dst, "\\37", 3);
	KUNIT_EXPECT_EQ(test, (unsigned char)dst[3], (unsigned char)GUARD);

	/* two-byte escape with 1 byte of room */
	memset(dst, GUARD, sizeof(dst));
	ret = string_escape_mem("\n", 1, dst, 1, ESCAPE_SPACE, NULL);
	KUNIT_EXPECT_EQ(test, ret, 2);
	KUNIT_EXPECT_EQ(test, dst[0], '\\');
	KUNIT_EXPECT_EQ(test, (unsigned char)dst[1], (unsigned char)GUARD);

	/* truncation in the middle of a multi-char sequence after passthrough */
	memset(dst, GUARD, sizeof(dst));
	ret = string_escape_mem("a\tb", 3, dst, 2, ESCAPE_SPACE, NULL);
	KUNIT_EXPECT_EQ(test, ret, 4);
	KUNIT_EXPECT_MEMEQ(test, dst, "a\\", 2);
	KUNIT_EXPECT_EQ(test, (unsigned char)dst[2], (unsigned char)GUARD);
}

static void agent_return_counts_full_length(struct kunit *test)
{
	char dst[2];
	char src[64];
	int ret;

	memset(src, 0xff, sizeof(src));
	memset(dst, GUARD, sizeof(dst));
	ret = string_escape_mem(src, sizeof(src), dst, 1, ESCAPE_HEX, NULL);
	KUNIT_EXPECT_EQ(test, ret, (int)(4 * sizeof(src)));
	KUNIT_EXPECT_EQ(test, dst[0], '\\');
	KUNIT_EXPECT_EQ(test, (unsigned char)dst[1], (unsigned char)GUARD);

	memset(dst, GUARD, sizeof(dst));
	ret = string_escape_mem(src, sizeof(src), dst, 1, ESCAPE_NULL, NULL);
	KUNIT_EXPECT_EQ(test, ret, (int)sizeof(src));
	KUNIT_EXPECT_EQ(test, (unsigned char)dst[0], 0xff);
	KUNIT_EXPECT_EQ(test, (unsigned char)dst[1], (unsigned char)GUARD);
}

static void agent_isz_respected(struct kunit *test)
{
	/* only @isz bytes are consumed, regardless of what follows in src */
	CHECKN("abc\n", 3, ESCAPE_SPACE, NULL, "abc");
	CHECKN("ab\n", 2, ESCAPE_HEX, NULL, "\\x61\\x62");
	CHECKN("a\n", 1, ESCAPE_ANY, NULL, "\\141");
	/* embedded NULs do not end the input */
	CHECKN("\0\0\0", 3, ESCAPE_NULL, NULL, "\\0\\0\\0");
	CHECKN("\0a", 2, 0, NULL, "\0a");
}

static void agent_all_bytes_octal_hex(struct kunit *test)
{
	static const char hexd[] = "0123456789abcdef";
	static char src[256];
	static char dst[4 * 256 + 1];
	static char exp[4 * 256 + 1];
	int i, ret;

	for (i = 0; i < 256; i++)
		src[i] = i;

	/* hex */
	for (i = 0; i < 256; i++) {
		exp[4 * i] = '\\';
		exp[4 * i + 1] = 'x';
		exp[4 * i + 2] = hexd[i >> 4];
		exp[4 * i + 3] = hexd[i & 0xf];
	}
	memset(dst, GUARD, sizeof(dst));
	ret = string_escape_mem(src, 256, dst, sizeof(dst) - 1, ESCAPE_HEX, NULL);
	KUNIT_EXPECT_EQ(test, ret, 4 * 256);
	KUNIT_EXPECT_MEMEQ(test, dst, exp, 4 * 256);
	KUNIT_EXPECT_EQ(test, (unsigned char)dst[4 * 256], (unsigned char)GUARD);

	/* octal */
	for (i = 0; i < 256; i++) {
		exp[4 * i] = '\\';
		exp[4 * i + 1] = '0' + ((i >> 6) & 7);
		exp[4 * i + 2] = '0' + ((i >> 3) & 7);
		exp[4 * i + 3] = '0' + (i & 7);
	}
	memset(dst, GUARD, sizeof(dst));
	ret = string_escape_mem(src, 256, dst, sizeof(dst) - 1, ESCAPE_OCTAL, NULL);
	KUNIT_EXPECT_EQ(test, ret, 4 * 256);
	KUNIT_EXPECT_MEMEQ(test, dst, exp, 4 * 256);
	KUNIT_EXPECT_EQ(test, (unsigned char)dst[4 * 256], (unsigned char)GUARD);

	/* passthrough of all bytes with no flags */
	memset(dst, GUARD, sizeof(dst));
	ret = string_escape_mem(src, 256, dst, sizeof(dst) - 1, 0, NULL);
	KUNIT_EXPECT_EQ(test, ret, 256);
	KUNIT_EXPECT_MEMEQ(test, dst, src, 256);
	KUNIT_EXPECT_EQ(test, (unsigned char)dst[256], (unsigned char)GUARD);
}

static void agent_np_na_classification_all_bytes(struct kunit *test)
{
	char src[1], dst[8];
	int c, ret;

	for (c = 0; c < 256; c++) {
		bool ascii = c < 0x80;
		bool print = (c >= 0x20 && c <= 0x7e) || c >= 0xa0;

		src[0] = c;

		ret = string_escape_mem(src, 1, dst, sizeof(dst),
					ESCAPE_NP | ESCAPE_HEX, NULL);
		KUNIT_EXPECT_EQ_MSG(test, ret, print ? 1 : 4, "NP c=%#x", c);

		ret = string_escape_mem(src, 1, dst, sizeof(dst),
					ESCAPE_NA | ESCAPE_HEX, NULL);
		KUNIT_EXPECT_EQ_MSG(test, ret, ascii ? 1 : 4, "NA c=%#x", c);

		ret = string_escape_mem(src, 1, dst, sizeof(dst),
					ESCAPE_NAP | ESCAPE_HEX, NULL);
		KUNIT_EXPECT_EQ_MSG(test, ret, (ascii && print) ? 1 : 4,
				    "NAP c=%#x", c);
	}
}

static void agent_long_mixed_input(struct kunit *test)
{
	static const char src[] =
		"Hello\tworld\n\"quoted\" \\back\\ \a\e\f\v\r\001\177\x80\xff end";
	static const char exp[] =
		"Hello\\tworld\\n\"quoted\" \\back\\ \\a\\e\\f\\v\\r"
		"\\001\\177\\200\xff end";
	static const char exp_any[] =
		"\\110\\145\\154\\154\\157\\t\\167\\157\\162\\154\\144\\n"
		"\\\"\\161\\165\\157\\164\\145\\144\\\"\\040\\\\\\142\\141"
		"\\143\\153\\\\\\040\\a\\e\\f\\v\\r\\001\\177\\200\\377"
		"\\040\\145\\156\\144";

	/* under NP, '"', '\\' and 0xff are printable and pass through */
	check_escape_all(test, src, sizeof(src) - 1, ESCAPE_ANY_NP, NULL, exp,
			 sizeof(exp) - 1);
	/* under ESCAPE_ANY alone every byte is escaped */
	check_escape_all(test, src, sizeof(src) - 1, ESCAPE_ANY, NULL, exp_any,
			 sizeof(exp_any) - 1);
}

