/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Test suite for string_unescape() from lib/string_helpers.c.
 */
#include <kunit/test.h>
#include <linux/string.h>
#include <linux/string_helpers.h>

#define BUF_SZ	64
#define FILL	0xA5

/*
 * Run string_unescape() on a fresh copy of @in with @flags and @size, then
 * check the return value, the output bytes (including the terminating NUL)
 * and that nothing past the NUL was touched.
 */
static void check_unescape(struct kunit *test, const char *in,
			   unsigned int flags, size_t size,
			   const char *expected, int expected_len)
{
	char src[BUF_SZ];
	char dst[BUF_SZ];
	int ret;
	int i;

	KUNIT_ASSERT_LT(test, strlen(in), (size_t)BUF_SZ);
	KUNIT_ASSERT_LT(test, expected_len, BUF_SZ - 1);

	strscpy(src, in, sizeof(src));
	memset(dst, FILL, sizeof(dst));

	ret = string_unescape(src, dst, size, flags);

	KUNIT_EXPECT_EQ_MSG(test, ret, expected_len,
			    "input \"%s\" flags %#x size %zu", in, flags, size);
	KUNIT_EXPECT_MEMEQ_MSG(test, dst, expected, expected_len,
			       "input \"%s\" flags %#x size %zu", in, flags, size);
	KUNIT_EXPECT_EQ_MSG(test, dst[expected_len], '\0',
			    "missing NUL for input \"%s\"", in);
	/* Nothing beyond the NUL terminator may be written. */
	for (i = expected_len + 1; i < BUF_SZ; i++)
		KUNIT_EXPECT_EQ_MSG(test, (unsigned char)dst[i], FILL,
				    "byte %d clobbered for input \"%s\"", i, in);
}

#define CHECK(test, in, flags, size, exp) \
	check_unescape(test, in, flags, size, exp, sizeof(exp) - 1)

/* ---- plain copies and no-flag behaviour ---------------------------------- */

static void agent_test_empty(struct kunit *test)
{
	CHECK(test, "", UNESCAPE_ANY, 0, "");
	CHECK(test, "", 0, 0, "");
	CHECK(test, "", UNESCAPE_ANY, 1, "");
	CHECK(test, "", UNESCAPE_ANY, BUF_SZ, "");
}

static void agent_test_plain_copy(struct kunit *test)
{
	CHECK(test, "a", UNESCAPE_ANY, 0, "a");
	CHECK(test, "hello world", UNESCAPE_ANY, 0, "hello world");
	CHECK(test, "hello world", 0, 0, "hello world");
	CHECK(test, "no escapes here 123 !@#", UNESCAPE_ANY, 0,
	      "no escapes here 123 !@#");
}

static void agent_test_no_flags(struct kunit *test)
{
	/* With no flags set every escape is passed through verbatim. */
	CHECK(test, "\\n", 0, 0, "\\n");
	CHECK(test, "\\t\\r\\v\\f", 0, 0, "\\t\\r\\v\\f");
	CHECK(test, "\\101", 0, 0, "\\101");
	CHECK(test, "\\x41", 0, 0, "\\x41");
	CHECK(test, "\\\\", 0, 0, "\\\\");
	CHECK(test, "\\\"\\a\\e", 0, 0, "\\\"\\a\\e");
	CHECK(test, "a\\nb", 0, 0, "a\\nb");
}

/* ---- UNESCAPE_SPACE ------------------------------------------------------ */

static void agent_test_space(struct kunit *test)
{
	CHECK(test, "\\n", UNESCAPE_SPACE, 0, "\n");
	CHECK(test, "\\r", UNESCAPE_SPACE, 0, "\r");
	CHECK(test, "\\t", UNESCAPE_SPACE, 0, "\t");
	CHECK(test, "\\v", UNESCAPE_SPACE, 0, "\v");
	CHECK(test, "\\f", UNESCAPE_SPACE, 0, "\f");
	CHECK(test, "\\n\\r\\t\\v\\f", UNESCAPE_SPACE, 0, "\n\r\t\v\f");
	CHECK(test, "a\\nb\\tc", UNESCAPE_SPACE, 0, "a\nb\tc");
	CHECK(test, "\\n\\n\\n", UNESCAPE_SPACE, 0, "\n\n\n");
}

static void agent_test_space_rejects_others(struct kunit *test)
{
	/* Only SPACE set: octal, hex and special must pass through. */
	CHECK(test, "\\101", UNESCAPE_SPACE, 0, "\\101");
	CHECK(test, "\\x41", UNESCAPE_SPACE, 0, "\\x41");
	CHECK(test, "\\\\", UNESCAPE_SPACE, 0, "\\\\");
	CHECK(test, "\\\"", UNESCAPE_SPACE, 0, "\\\"");
	CHECK(test, "\\a", UNESCAPE_SPACE, 0, "\\a");
	CHECK(test, "\\e", UNESCAPE_SPACE, 0, "\\e");
	/* 'N', 'b', 's' are not space escapes. */
	CHECK(test, "\\N", UNESCAPE_SPACE, 0, "\\N");
	CHECK(test, "\\b", UNESCAPE_SPACE, 0, "\\b");
	CHECK(test, "\\s", UNESCAPE_SPACE, 0, "\\s");
}

/* ---- UNESCAPE_OCTAL ------------------------------------------------------ */

static void agent_test_octal_basic(struct kunit *test)
{
	CHECK(test, "\\101", UNESCAPE_OCTAL, 0, "A");
	CHECK(test, "\\141", UNESCAPE_OCTAL, 0, "a");
	CHECK(test, "\\060", UNESCAPE_OCTAL, 0, "0");
	CHECK(test, "\\101\\102\\103", UNESCAPE_OCTAL, 0, "ABC");
	CHECK(test, "x\\101y", UNESCAPE_OCTAL, 0, "xAy");
	/* 1 and 2 digit forms. */
	CHECK(test, "\\7", UNESCAPE_OCTAL, 0, "\007");
	CHECK(test, "\\1", UNESCAPE_OCTAL, 0, "\001");
	CHECK(test, "\\77", UNESCAPE_OCTAL, 0, "\077");
	CHECK(test, "\\12", UNESCAPE_OCTAL, 0, "\n");
}

static void agent_test_octal_digit_limits(struct kunit *test)
{
	/* Exactly 3 digits consumed; 4th digit is literal. */
	CHECK(test, "\\1011", UNESCAPE_OCTAL, 0, "A1");
	CHECK(test, "\\1017", UNESCAPE_OCTAL, 0, "A7");
	/* Non-octal digit right after stops the sequence. */
	CHECK(test, "\\18", UNESCAPE_OCTAL, 0, "\0018");
	CHECK(test, "\\19", UNESCAPE_OCTAL, 0, "\0019");
	CHECK(test, "\\7a", UNESCAPE_OCTAL, 0, "\007a");
	CHECK(test, "\\101z", UNESCAPE_OCTAL, 0, "Az");
	/* A one-digit sequence at end of string. */
	CHECK(test, "ab\\7", UNESCAPE_OCTAL, 0, "ab\007");
}

static void agent_test_octal_overflow_guard(struct kunit *test)
{
	/*
	 * A third digit is only accepted while the accumulated value is
	 * still below 32, i.e. the result must fit in a byte.
	 */
	CHECK(test, "\\377", UNESCAPE_OCTAL, 0, "\377");
	CHECK(test, "\\200", UNESCAPE_OCTAL, 0, "\200");
	CHECK(test, "\\177", UNESCAPE_OCTAL, 0, "\177");
	CHECK(test, "\\37", UNESCAPE_OCTAL, 0, "\037");
	/* \40 is 32: a third digit must not be consumed. */
	CHECK(test, "\\400", UNESCAPE_OCTAL, 0, " 0");
	CHECK(test, "\\40", UNESCAPE_OCTAL, 0, " ");
	CHECK(test, "\\777", UNESCAPE_OCTAL, 0, "?7");
	CHECK(test, "\\477", UNESCAPE_OCTAL, 0, "'7");
	/* \37 is 31: a third digit is still consumed. */
	CHECK(test, "\\377\\376", UNESCAPE_OCTAL, 0, "\377\376");
}

static void agent_test_octal_nul(struct kunit *test)
{
	/* \0 variants produce a real NUL byte in the output. */
	CHECK(test, "\\0", UNESCAPE_OCTAL, 0, "\0");
	CHECK(test, "\\00", UNESCAPE_OCTAL, 0, "\0");
	CHECK(test, "\\000", UNESCAPE_OCTAL, 0, "\0");
	CHECK(test, "\\0000", UNESCAPE_OCTAL, 0, "\0" "0");
	CHECK(test, "a\\0b", UNESCAPE_OCTAL, 0, "a\0b");
}

static void agent_test_octal_rejects_others(struct kunit *test)
{
	CHECK(test, "\\8", UNESCAPE_OCTAL, 0, "\\8");
	CHECK(test, "\\9", UNESCAPE_OCTAL, 0, "\\9");
	CHECK(test, "\\n", UNESCAPE_OCTAL, 0, "\\n");
	CHECK(test, "\\x41", UNESCAPE_OCTAL, 0, "\\x41");
	CHECK(test, "\\\\", UNESCAPE_OCTAL, 0, "\\\\");
	CHECK(test, "\\a", UNESCAPE_OCTAL, 0, "\\a");
}

/* ---- UNESCAPE_HEX -------------------------------------------------------- */

static void agent_test_hex_basic(struct kunit *test)
{
	CHECK(test, "\\x41", UNESCAPE_HEX, 0, "A");
	CHECK(test, "\\x61", UNESCAPE_HEX, 0, "a");
	CHECK(test, "\\x30", UNESCAPE_HEX, 0, "0");
	CHECK(test, "\\x41\\x42\\x43", UNESCAPE_HEX, 0, "ABC");
	CHECK(test, "p\\x41q", UNESCAPE_HEX, 0, "pAq");
	/* Upper and lower case digits. */
	CHECK(test, "\\x4A", UNESCAPE_HEX, 0, "J");
	CHECK(test, "\\x4a", UNESCAPE_HEX, 0, "J");
	CHECK(test, "\\xFF", UNESCAPE_HEX, 0, "\377");
	CHECK(test, "\\xff", UNESCAPE_HEX, 0, "\377");
	CHECK(test, "\\xaB", UNESCAPE_HEX, 0, "\253");
	CHECK(test, "\\x80", UNESCAPE_HEX, 0, "\200");
	CHECK(test, "\\x7f", UNESCAPE_HEX, 0, "\177");
	CHECK(test, "\\x00", UNESCAPE_HEX, 0, "\0");
	CHECK(test, "\\x0", UNESCAPE_HEX, 0, "\0");
}

static void agent_test_hex_digit_limits(struct kunit *test)
{
	/* One-digit form. */
	CHECK(test, "\\x4", UNESCAPE_HEX, 0, "\004");
	CHECK(test, "\\xf", UNESCAPE_HEX, 0, "\017");
	CHECK(test, "\\x4g", UNESCAPE_HEX, 0, "\004g");
	CHECK(test, "\\x4 ", UNESCAPE_HEX, 0, "\004 ");
	/* At most two digits are consumed; the third is literal. */
	CHECK(test, "\\x411", UNESCAPE_HEX, 0, "A1");
	CHECK(test, "\\x41f", UNESCAPE_HEX, 0, "Af");
	CHECK(test, "\\x4141", UNESCAPE_HEX, 0, "A41");
}

static void agent_test_hex_invalid(struct kunit *test)
{
	/* "\x" with no hex digit is left untouched. */
	CHECK(test, "\\x", UNESCAPE_HEX, 0, "\\x");
	CHECK(test, "\\xg", UNESCAPE_HEX, 0, "\\xg");
	CHECK(test, "\\xG1", UNESCAPE_HEX, 0, "\\xG1");
	CHECK(test, "\\x ", UNESCAPE_HEX, 0, "\\x ");
	CHECK(test, "a\\xzb", UNESCAPE_HEX, 0, "a\\xzb");
	/* Upper-case 'X' is not a hex escape. */
	CHECK(test, "\\X41", UNESCAPE_HEX, 0, "\\X41");
}

static void agent_test_hex_rejects_others(struct kunit *test)
{
	CHECK(test, "\\n", UNESCAPE_HEX, 0, "\\n");
	CHECK(test, "\\101", UNESCAPE_HEX, 0, "\\101");
	CHECK(test, "\\\\", UNESCAPE_HEX, 0, "\\\\");
	CHECK(test, "\\\"", UNESCAPE_HEX, 0, "\\\"");
}

/* ---- UNESCAPE_SPECIAL ---------------------------------------------------- */

static void agent_test_special(struct kunit *test)
{
	CHECK(test, "\\\"", UNESCAPE_SPECIAL, 0, "\"");
	CHECK(test, "\\\\", UNESCAPE_SPECIAL, 0, "\\");
	CHECK(test, "\\a", UNESCAPE_SPECIAL, 0, "\a");
	CHECK(test, "\\e", UNESCAPE_SPECIAL, 0, "\033");
	CHECK(test, "\\\"\\\\\\a\\e", UNESCAPE_SPECIAL, 0, "\"\\\a\033");
	CHECK(test, "say \\\"hi\\\"", UNESCAPE_SPECIAL, 0, "say \"hi\"");
	/* "\\\\" is two escaped backslashes -> two backslashes. */
	CHECK(test, "\\\\\\\\", UNESCAPE_SPECIAL, 0, "\\\\");
	/* "\\n" is an escaped backslash followed by a literal n. */
	CHECK(test, "\\\\n", UNESCAPE_SPECIAL, 0, "\\n");
	CHECK(test, "\\\\n", UNESCAPE_ANY, 0, "\\n");
}

static void agent_test_special_rejects_others(struct kunit *test)
{
	CHECK(test, "\\n", UNESCAPE_SPECIAL, 0, "\\n");
	CHECK(test, "\\101", UNESCAPE_SPECIAL, 0, "\\101");
	CHECK(test, "\\x41", UNESCAPE_SPECIAL, 0, "\\x41");
	/* Single quote and 'b' are not special escapes. */
	CHECK(test, "\\'", UNESCAPE_SPECIAL, 0, "\\'");
	CHECK(test, "\\b", UNESCAPE_SPECIAL, 0, "\\b");
	CHECK(test, "\\E", UNESCAPE_SPECIAL, 0, "\\E");
	CHECK(test, "\\A", UNESCAPE_SPECIAL, 0, "\\A");
}

/* ---- combinations / UNESCAPE_ANY ---------------------------------------- */

static void agent_test_any_mixed(struct kunit *test)
{
	CHECK(test, "\\t\\x41\\101\\\\\\\"", UNESCAPE_ANY, 0, "\tAA\\\"");
	CHECK(test, "\\n\\101\\x42\\e", UNESCAPE_ANY, 0, "\nAB\033");
	CHECK(test, "a\\nb\\x43d\\104e\\\\f", UNESCAPE_ANY, 0,
	      "a\nbCdDe\\f");
	/* Unknown escapes survive even with every flag set. */
	CHECK(test, "\\q", UNESCAPE_ANY, 0, "\\q");
	CHECK(test, "\\8", UNESCAPE_ANY, 0, "\\8");
	CHECK(test, "\\z\\n", UNESCAPE_ANY, 0, "\\z\n");
	CHECK(test, "\\xg", UNESCAPE_ANY, 0, "\\xg");
	CHECK(test, "\\'", UNESCAPE_ANY, 0, "\\'");
}

static void agent_test_flag_subsets(struct kunit *test)
{
	unsigned int f;

	f = UNESCAPE_SPACE | UNESCAPE_HEX;
	CHECK(test, "\\n\\x41\\101\\\\", f, 0, "\nA\\101\\\\");

	f = UNESCAPE_OCTAL | UNESCAPE_SPECIAL;
	CHECK(test, "\\n\\x41\\101\\\\", f, 0, "\\n\\x41A\\");

	f = UNESCAPE_SPACE | UNESCAPE_SPECIAL;
	CHECK(test, "\\t\\e\\12\\x9", f, 0, "\t\033\\12\\x9");

	f = UNESCAPE_OCTAL | UNESCAPE_HEX;
	CHECK(test, "\\12\\x9\\t\\a", f, 0, "\n\t\\t\\a");
}

static void agent_test_any_value(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, UNESCAPE_ANY,
			UNESCAPE_SPACE | UNESCAPE_OCTAL | UNESCAPE_HEX |
			UNESCAPE_SPECIAL);
	/* Flag bits must be distinct. */
	KUNIT_EXPECT_EQ(test, UNESCAPE_SPACE & UNESCAPE_OCTAL, 0);
	KUNIT_EXPECT_EQ(test, UNESCAPE_SPACE & UNESCAPE_HEX, 0);
	KUNIT_EXPECT_EQ(test, UNESCAPE_SPACE & UNESCAPE_SPECIAL, 0);
	KUNIT_EXPECT_EQ(test, UNESCAPE_OCTAL & UNESCAPE_HEX, 0);
	KUNIT_EXPECT_EQ(test, UNESCAPE_OCTAL & UNESCAPE_SPECIAL, 0);
	KUNIT_EXPECT_EQ(test, UNESCAPE_HEX & UNESCAPE_SPECIAL, 0);
}

/* ---- backslash edge cases ------------------------------------------------ */

static void agent_test_trailing_backslash(struct kunit *test)
{
	CHECK(test, "\\", UNESCAPE_ANY, 0, "\\");
	CHECK(test, "\\", 0, 0, "\\");
	CHECK(test, "abc\\", UNESCAPE_ANY, 0, "abc\\");
	CHECK(test, "\\n\\", UNESCAPE_ANY, 0, "\n\\");
	/* Three backslashes: one escaped pair plus a trailing one. */
	CHECK(test, "\\\\\\", UNESCAPE_ANY, 0, "\\\\");
	CHECK(test, "\\\\\\", UNESCAPE_SPACE, 0, "\\\\\\");
}

static void agent_test_backslash_sequences(struct kunit *test)
{
	/* "\\\n" (escaped backslash + \n) -> backslash, newline. */
	CHECK(test, "\\\\\\n", UNESCAPE_ANY, 0, "\\\n");
	/* Without SPECIAL, the first "\\" is kept and then "\n" unescaped. */
	CHECK(test, "\\\\\\n", UNESCAPE_SPACE, 0, "\\\\\n");
	/* Escaped backslash followed by an x and hex digits is literal. */
	CHECK(test, "\\\\x41", UNESCAPE_ANY, 0, "\\x41");
	/* Escaped backslash followed by octal digits is literal. */
	CHECK(test, "\\\\101", UNESCAPE_ANY, 0, "\\101");
}

/* ---- size handling ------------------------------------------------------- */

static void agent_test_size_unlimited(struct kunit *test)
{
	/* size 0 means "no limit": a long input is fully processed. */
	CHECK(test, "0123456789012345678901234567890123456789", UNESCAPE_ANY, 0,
	      "0123456789012345678901234567890123456789");
	CHECK(test, "\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n", UNESCAPE_ANY, 0,
	      "\n\n\n\n\n\n\n\n\n\n");
}

static void agent_test_size_truncates_plain(struct kunit *test)
{
	/* size counts the trailing NUL, so size-1 chars are copied. */
	CHECK(test, "abcdef", UNESCAPE_ANY, 1, "");
	CHECK(test, "abcdef", UNESCAPE_ANY, 2, "a");
	CHECK(test, "abcdef", UNESCAPE_ANY, 3, "ab");
	CHECK(test, "abcdef", UNESCAPE_ANY, 6, "abcde");
	CHECK(test, "abcdef", UNESCAPE_ANY, 7, "abcdef");
	CHECK(test, "abcdef", UNESCAPE_ANY, 8, "abcdef");
	CHECK(test, "abcdef", UNESCAPE_ANY, BUF_SZ, "abcdef");
}

static void agent_test_size_exact_fit(struct kunit *test)
{
	/* Output exactly fills the buffer including the NUL. */
	CHECK(test, "\\n", UNESCAPE_ANY, 3, "\n");
	CHECK(test, "\\x41", UNESCAPE_ANY, 3, "A");
	CHECK(test, "\\101", UNESCAPE_ANY, 3, "A");
	CHECK(test, "\\\\", UNESCAPE_ANY, 3, "\\");
	CHECK(test, "a\\nb", UNESCAPE_ANY, 5, "a\nb");
	CHECK(test, "\\n\\t", UNESCAPE_ANY, 5, "\n\t");
	CHECK(test, "\\x41\\x42", UNESCAPE_ANY, 5, "AB");
}

static void agent_test_size_escape_needs_room(struct kunit *test)
{
	/*
	 * An escape sequence is only decoded if there is room for the
	 * decoded byte and the NUL; with size 2 for "\n", only the
	 * backslash itself fits and it is copied literally.
	 */
	CHECK(test, "\\n", UNESCAPE_ANY, 2, "\\");
	CHECK(test, "\\x41", UNESCAPE_ANY, 2, "\\");
	CHECK(test, "\\101", UNESCAPE_ANY, 2, "\\");
	CHECK(test, "\\\\", UNESCAPE_ANY, 2, "\\");
	CHECK(test, "\\n", UNESCAPE_ANY, 1, "");

	/* Escape in the middle hitting the limit. */
	CHECK(test, "a\\nb", UNESCAPE_ANY, 2, "a");
	CHECK(test, "a\\nb", UNESCAPE_ANY, 3, "a\\");
	CHECK(test, "a\\nb", UNESCAPE_ANY, 4, "a\n");
	CHECK(test, "a\\nb", UNESCAPE_ANY, 5, "a\nb");
	CHECK(test, "a\\nb", UNESCAPE_ANY, 6, "a\nb");

	/* Multi-char escapes count as one output byte. */
	CHECK(test, "ab\\x41cd", UNESCAPE_ANY, 4, "ab\\");
	CHECK(test, "ab\\x41cd", UNESCAPE_ANY, 5, "abA");
	CHECK(test, "ab\\x41cd", UNESCAPE_ANY, 6, "abAc");
	CHECK(test, "ab\\101cd", UNESCAPE_ANY, 5, "abA");
	CHECK(test, "ab\\101cd", UNESCAPE_ANY, 6, "abAc");
}

static void agent_test_size_unknown_escape(struct kunit *test)
{
	/*
	 * An unrecognised escape expands to two output bytes; a buffer
	 * with room for only one gets just the backslash.
	 */
	CHECK(test, "\\q", UNESCAPE_ANY, 2, "\\");
	CHECK(test, "\\q", UNESCAPE_ANY, 3, "\\q");
	CHECK(test, "\\q", UNESCAPE_ANY, 4, "\\q");
	CHECK(test, "\\qz", UNESCAPE_ANY, 3, "\\q");
	CHECK(test, "\\qz", UNESCAPE_ANY, 4, "\\qz");
	CHECK(test, "\\n", 0, 2, "\\");
	CHECK(test, "\\n", 0, 3, "\\n");
}

/* ---- in-place operation and dst independence --------------------------- */

static void agent_test_in_place(struct kunit *test)
{
	char buf[BUF_SZ];
	int ret;

	strscpy(buf, "a\\nb\\x41\\101\\\\\\\"end", sizeof(buf));
	ret = string_unescape(buf, buf, 0, UNESCAPE_ANY);
	KUNIT_EXPECT_EQ(test, ret, 10);
	KUNIT_EXPECT_MEMEQ(test, buf, "a\nbAA\\\"end\0", 11);

	strscpy(buf, "\\n\\n\\n\\n", sizeof(buf));
	ret = string_unescape(buf, buf, 0, UNESCAPE_SPACE);
	KUNIT_EXPECT_EQ(test, ret, 4);
	KUNIT_EXPECT_MEMEQ(test, buf, "\n\n\n\n\0", 5);

	strscpy(buf, "plain", sizeof(buf));
	ret = string_unescape(buf, buf, sizeof(buf), UNESCAPE_ANY);
	KUNIT_EXPECT_EQ(test, ret, 5);
	KUNIT_EXPECT_STREQ(test, buf, "plain");

	/* In-place with a size limit: no room to decode, backslash kept. */
	strscpy(buf, "abc\\ndef", sizeof(buf));
	ret = string_unescape(buf, buf, 5, UNESCAPE_ANY);
	KUNIT_EXPECT_EQ(test, ret, 4);
	KUNIT_EXPECT_MEMEQ(test, buf, "abc\\\0", 5);

	/* In-place with just enough room to decode the escape. */
	strscpy(buf, "abc\\ndef", sizeof(buf));
	ret = string_unescape(buf, buf, 6, UNESCAPE_ANY);
	KUNIT_EXPECT_EQ(test, ret, 4);
	KUNIT_EXPECT_MEMEQ(test, buf, "abc\n\0", 5);
}

static void agent_test_source_untouched(struct kunit *test)
{
	char src[BUF_SZ];
	char dst[BUF_SZ];
	int ret;

	strscpy(src, "x\\ny\\x41z", sizeof(src));
	ret = string_unescape(src, dst, sizeof(dst), UNESCAPE_ANY);
	KUNIT_EXPECT_EQ(test, ret, 5);
	KUNIT_EXPECT_STREQ(test, dst, "x\nyAz");
	KUNIT_EXPECT_STREQ(test, src, "x\\ny\\x41z");
}

static void agent_test_return_matches_strlen(struct kunit *test)
{
	static const char * const inputs[] = {
		"", "a", "abc", "\\n", "\\x41\\102", "a\\\\b", "\\q", "tail\\",
		"\\x", "\\400", "\\0000",
	};
	char dst[BUF_SZ];
	char src[BUF_SZ];
	int ret;
	int i;

	for (i = 0; i < ARRAY_SIZE(inputs); i++) {
		/* Skip inputs that legitimately produce embedded NULs. */
		if (strstr(inputs[i], "\\0"))
			continue;
		strscpy(src, inputs[i], sizeof(src));
		ret = string_unescape(src, dst, sizeof(dst), UNESCAPE_ANY);
		KUNIT_EXPECT_EQ_MSG(test, ret, (int)strlen(dst),
				    "input \"%s\"", inputs[i]);
		KUNIT_EXPECT_LE_MSG(test, ret, (int)strlen(inputs[i]),
				    "output longer than input for \"%s\"",
				    inputs[i]);
	}
}

static void agent_test_high_bytes_passthrough(struct kunit *test)
{
	/* Non-ASCII bytes in the source are copied verbatim. */
	CHECK(test, "\200\377\201", UNESCAPE_ANY, 0, "\200\377\201");
	CHECK(test, "\\n\377\\t", UNESCAPE_ANY, 0, "\n\377\t");
	CHECK(test, "\377\\\377", UNESCAPE_ANY, 0, "\377\\\377");
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(agent_test_empty),
	KUNIT_CASE(agent_test_plain_copy),
	KUNIT_CASE(agent_test_no_flags),
	KUNIT_CASE(agent_test_space),
	KUNIT_CASE(agent_test_space_rejects_others),
	KUNIT_CASE(agent_test_octal_basic),
	KUNIT_CASE(agent_test_octal_digit_limits),
	KUNIT_CASE(agent_test_octal_overflow_guard),
	KUNIT_CASE(agent_test_octal_nul),
	KUNIT_CASE(agent_test_octal_rejects_others),
	KUNIT_CASE(agent_test_hex_basic),
	KUNIT_CASE(agent_test_hex_digit_limits),
	KUNIT_CASE(agent_test_hex_invalid),
	KUNIT_CASE(agent_test_hex_rejects_others),
	KUNIT_CASE(agent_test_special),
	KUNIT_CASE(agent_test_special_rejects_others),
	KUNIT_CASE(agent_test_any_mixed),
	KUNIT_CASE(agent_test_flag_subsets),
	KUNIT_CASE(agent_test_any_value),
	KUNIT_CASE(agent_test_trailing_backslash),
	KUNIT_CASE(agent_test_backslash_sequences),
	KUNIT_CASE(agent_test_size_unlimited),
	KUNIT_CASE(agent_test_size_truncates_plain),
	KUNIT_CASE(agent_test_size_exact_fit),
	KUNIT_CASE(agent_test_size_escape_needs_room),
	KUNIT_CASE(agent_test_size_unknown_escape),
	KUNIT_CASE(agent_test_in_place),
	KUNIT_CASE(agent_test_source_untouched),
	KUNIT_CASE(agent_test_return_matches_strlen),
	KUNIT_CASE(agent_test_high_bytes_passthrough),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};

kunit_test_suite(agent_test_suite);

