/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Tests for get_option() in lib/cmdline.c.
 */

#include <kunit/test.h>
#include <linux/kernel.h>
#include <linux/limits.h>

/*
 * Helper: run get_option() on @input, check return value, parsed value and
 * how far the cursor advanced (in bytes from the start of @input).
 */
static void check_option(struct kunit *test, const char *input, int exp_ret,
			 int exp_val, size_t exp_advance)
{
	char *str = (char *)input;
	int val = 0x5a5a5a5a;
	int ret;

	ret = get_option(&str, &val);
	KUNIT_EXPECT_EQ_MSG(test, ret, exp_ret, "input=\"%s\"", input);
	KUNIT_EXPECT_EQ_MSG(test, val, exp_val, "input=\"%s\"", input);
	KUNIT_EXPECT_PTR_EQ_MSG(test, str, (char *)input + exp_advance,
				"input=\"%s\" advanced %zd", input,
				(ssize_t)(str - input));
}

static void agent_test_simple_decimal(struct kunit *test)
{
	check_option(test, "123", 1, 123, 3);
	check_option(test, "7", 1, 7, 1);
	check_option(test, "0", 1, 0, 1);
	check_option(test, "42abc", 1, 42, 2);
	check_option(test, "9 ", 1, 9, 1);
}

static void agent_test_negative(struct kunit *test)
{
	check_option(test, "-5", 1, -5, 2);
	check_option(test, "-0", 1, 0, 2);
	check_option(test, "-123,", 2, -123, 5);
	check_option(test, "-1-3", 3, -1, 2);
}

static void agent_test_comma(struct kunit *test)
{
	check_option(test, "123,456", 2, 123, 4);
	check_option(test, "5,", 2, 5, 2);
	check_option(test, "0,", 2, 0, 2);
	check_option(test, "1,,", 2, 1, 2);
}

static void agent_test_range(struct kunit *test)
{
	/* Hyphen is reported but not consumed. */
	check_option(test, "1-5", 3, 1, 1);
	check_option(test, "10-", 3, 10, 2);
	check_option(test, "0-3", 3, 0, 1);
}

static void agent_test_bases(struct kunit *test)
{
	check_option(test, "0x10", 1, 16, 4);
	check_option(test, "0X1f", 1, 31, 4);
	check_option(test, "010", 1, 8, 3);
	check_option(test, "-0x10", 1, -16, 5);
	check_option(test, "0xff,", 2, 255, 5);
	/* "0x" without hex digits is parsed as octal "0" followed by "x". */
	check_option(test, "0x", 1, 0, 1);
	check_option(test, "0xg", 1, 0, 1);
	/* Octal with a non-octal digit stops at that digit. */
	check_option(test, "08", 1, 0, 1);
}

static void agent_test_int_limits(struct kunit *test)
{
	check_option(test, "2147483647", 1, INT_MAX, 10);
	check_option(test, "-2147483648", 1, INT_MIN, 11);
	check_option(test, "0x7fffffff", 1, INT_MAX, 10);
	/* Values wrap through the int conversion but still count as found. */
	check_option(test, "0xffffffff", 1, -1, 10);
	check_option(test, "4294967296", 1, 0, 10);
}

static void agent_test_no_int(struct kunit *test)
{
	/* No digits: return 0, *pint is set to 0, cursor does not move. */
	check_option(test, "abc", 0, 0, 0);
	check_option(test, ",", 0, 0, 0);
	check_option(test, ",5", 0, 0, 0);
	check_option(test, " 5", 0, 0, 0);
	check_option(test, "+5", 0, 0, 0);
	check_option(test, "x10", 0, 0, 0);
}

static void agent_test_empty_and_null(struct kunit *test)
{
	char *str = "";
	char *null_str = NULL;
	int val = 77;

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 0);
	/* Early return: pint must be left untouched. */
	KUNIT_EXPECT_EQ(test, val, 77);
	KUNIT_EXPECT_PTR_EQ(test, str, (char *)"" + 0);

	KUNIT_EXPECT_EQ(test, get_option(&null_str, &val), 0);
	KUNIT_EXPECT_EQ(test, val, 77);
	KUNIT_EXPECT_NULL(test, null_str);

	/* NULL pint with empty string is fine too. */
	KUNIT_EXPECT_EQ(test, get_option(&str, NULL), 0);
}

static void agent_test_lone_hyphen(struct kunit *test)
{
	/* A leading hyphen with no integer is consumed, but reports 0. */
	check_option(test, "-", 0, 0, 1);
	check_option(test, "-,", 0, 0, 1);
	check_option(test, "-abc", 0, 0, 1);
	/* A second hyphen is not an integer: only the first is consumed. */
	check_option(test, "--5", 0, 0, 1);
}

static void agent_test_null_pint(struct kunit *test)
{
	char input[] = "12,34-5";
	char *str = input;

	KUNIT_EXPECT_EQ(test, get_option(&str, NULL), 2);
	KUNIT_EXPECT_PTR_EQ(test, str, input + 3);
	KUNIT_EXPECT_EQ(test, get_option(&str, NULL), 3);
	KUNIT_EXPECT_PTR_EQ(test, str, input + 5);
	/* At the hyphen, it is now read as a negative sign: "-5". */
	KUNIT_EXPECT_EQ(test, get_option(&str, NULL), 1);
	KUNIT_EXPECT_PTR_EQ(test, str, input + 7);
	/* End of string. */
	KUNIT_EXPECT_EQ(test, get_option(&str, NULL), 0);
	KUNIT_EXPECT_PTR_EQ(test, str, input + 7);
}

static void agent_test_sequential(struct kunit *test)
{
	char input[] = "1,22,-3,0x4-8,";
	char *str = input;
	int val = -1;

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 2);
	KUNIT_EXPECT_EQ(test, val, 1);
	KUNIT_EXPECT_PTR_EQ(test, str, input + 2);

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 2);
	KUNIT_EXPECT_EQ(test, val, 22);
	KUNIT_EXPECT_PTR_EQ(test, str, input + 5);

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 2);
	KUNIT_EXPECT_EQ(test, val, -3);
	KUNIT_EXPECT_PTR_EQ(test, str, input + 8);

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 3);
	KUNIT_EXPECT_EQ(test, val, 4);
	KUNIT_EXPECT_PTR_EQ(test, str, input + 11);
	KUNIT_EXPECT_EQ(test, *str, '-');

	/* Caller skips the hyphen; range upper bound followed by comma. */
	str++;
	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 2);
	KUNIT_EXPECT_EQ(test, val, 8);
	KUNIT_EXPECT_PTR_EQ(test, str, input + 14);

	/* End of string. */
	val = 99;
	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 0);
	KUNIT_EXPECT_EQ(test, val, 99);
	KUNIT_EXPECT_PTR_EQ(test, str, input + 14);
}

static void agent_test_delimiters_not_consumed(struct kunit *test)
{
	/* Only a comma is consumed; any other trailing byte is left alone. */
	check_option(test, "3;4", 1, 3, 1);
	check_option(test, "3.4", 1, 3, 1);
	check_option(test, "3:4", 1, 3, 1);
	check_option(test, "3\n", 1, 3, 1);
}

static struct kunit_case agent_test_cases[] = {
