// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Tests for memparse() in lib/cmdline.c.
 */

#include <kunit/test.h>
#include <linux/kernel.h>
#include <linux/string.h>

/* Parse @str and check value and number of consumed characters. */
static void check_memparse(struct kunit *test, const char *str,
			   unsigned long long expect, size_t consumed)
{
	char *end = NULL;
	unsigned long long ret;

	ret = memparse(str, &end);
	KUNIT_EXPECT_EQ_MSG(test, ret, expect, "input \"%s\"", str);
	KUNIT_EXPECT_PTR_EQ_MSG(test, end, (char *)str + consumed,
				"input \"%s\": end offset %td, expected %zu",
				str, end - str, consumed);
}

static void memparse_plain_decimal(struct kunit *test)
{
	check_memparse(test, "0", 0, 1);
	check_memparse(test, "1", 1, 1);
	check_memparse(test, "9", 9, 1);
	check_memparse(test, "10", 10, 2);
	check_memparse(test, "123456789", 123456789ULL, 9);
	check_memparse(test, "4294967295", 4294967295ULL, 10);
	check_memparse(test, "4294967296", 4294967296ULL, 10);
	check_memparse(test, "18446744073709551615", ULLONG_MAX, 20);
}

static void memparse_hex_and_octal(struct kunit *test)
{
	check_memparse(test, "0x10", 0x10, 4);
	check_memparse(test, "0X10", 0x10, 4);
	check_memparse(test, "0xff", 0xff, 4);
	check_memparse(test, "0xFF", 0xff, 4);
	check_memparse(test, "0xdeadbeef", 0xdeadbeefULL, 10);
	check_memparse(test, "0xffffffffffffffff", ULLONG_MAX, 18);
	check_memparse(test, "0x0", 0, 3);
	/* leading zero means octal with base 0 */
	check_memparse(test, "010", 8, 3);
	check_memparse(test, "0777", 0777, 4);
	check_memparse(test, "00", 0, 2);
}

static void memparse_suffix_k(struct kunit *test)
{
	check_memparse(test, "1k", 1ULL << 10, 2);
	check_memparse(test, "1K", 1ULL << 10, 2);
	check_memparse(test, "0k", 0, 2);
	check_memparse(test, "3K", 3ULL << 10, 2);
	check_memparse(test, "1023k", 1023ULL << 10, 5);
	check_memparse(test, "1024K", 1ULL << 20, 5);
	check_memparse(test, "0x10k", 16ULL << 10, 5);
}

static void memparse_suffix_m(struct kunit *test)
{
	check_memparse(test, "1m", 1ULL << 20, 2);
	check_memparse(test, "1M", 1ULL << 20, 2);
	check_memparse(test, "0M", 0, 2);
	check_memparse(test, "512m", 512ULL << 20, 4);
	check_memparse(test, "0x3M", 3ULL << 20, 4);
}

static void memparse_suffix_g(struct kunit *test)
{
	check_memparse(test, "1g", 1ULL << 30, 2);
	check_memparse(test, "1G", 1ULL << 30, 2);
	check_memparse(test, "4G", 4ULL << 30, 2);
	check_memparse(test, "0g", 0, 2);
}

static void memparse_suffix_t(struct kunit *test)
{
	check_memparse(test, "1t", 1ULL << 40, 2);
	check_memparse(test, "1T", 1ULL << 40, 2);
	check_memparse(test, "7T", 7ULL << 40, 2);
}

static void memparse_suffix_p(struct kunit *test)
{
	check_memparse(test, "1p", 1ULL << 50, 2);
	check_memparse(test, "1P", 1ULL << 50, 2);
	check_memparse(test, "2P", 2ULL << 50, 2);
}

static void memparse_suffix_e(struct kunit *test)
{
	check_memparse(test, "1e", 1ULL << 60, 2);
	check_memparse(test, "1E", 1ULL << 60, 2);
	check_memparse(test, "15E", 15ULL << 60, 3);
}

/* Each suffix must be exactly 1024x the one below it. */
static void memparse_suffix_ladder(struct kunit *test)
{
	static const char * const s[] = { "1", "1K", "1M", "1G", "1T", "1P", "1E" };
	unsigned long long prev = memparse(s[0], NULL);
	int i;

	KUNIT_EXPECT_EQ(test, prev, 1ULL);
	for (i = 1; i < ARRAY_SIZE(s); i++) {
		unsigned long long cur = memparse(s[i], NULL);

		KUNIT_EXPECT_EQ_MSG(test, cur, prev * 1024, "suffix %s", s[i]);
		prev = cur;
	}
}

/* Shifting past 64 bits wraps/truncates; no sign extension or crash. */
static void memparse_overflow(struct kunit *test)
{
	check_memparse(test, "16E", 0, 3);
	check_memparse(test, "0x8000000000000000K", 0, 19);
	check_memparse(test, "0xffffffffffffffffK", ULLONG_MAX << 10, 19);
	check_memparse(test, "1024E", 0, 5);
	check_memparse(test, "0x1000000000000M", 0, 16);
	check_memparse(test, "0x10000000000M", 1ULL << 60, 14);
}

/* Only one suffix letter is consumed; trailing text is left alone. */
static void memparse_single_suffix_only(struct kunit *test)
{
	check_memparse(test, "1KK", 1ULL << 10, 2);
	check_memparse(test, "1kM", 1ULL << 10, 2);
	check_memparse(test, "1MG", 1ULL << 20, 2);
	check_memparse(test, "1Kb", 1ULL << 10, 2);
	check_memparse(test, "2MB", 2ULL << 20, 2);
	check_memparse(test, "1GiB", 1ULL << 30, 2);
}

static void memparse_unknown_suffix(struct kunit *test)
{
	check_memparse(test, "1B", 1, 1);
	check_memparse(test, "1b", 1, 1);
	check_memparse(test, "5x", 5, 1);
	check_memparse(test, "5X", 5, 1);
	check_memparse(test, "7z", 7, 1);
	check_memparse(test, "7Z", 7, 1);
	check_memparse(test, "7j", 7, 1);
	check_memparse(test, "7l", 7, 1);
	check_memparse(test, "7q", 7, 1);
	check_memparse(test, "7f", 7, 1);
	check_memparse(test, "7F", 7, 1);
	check_memparse(test, "7d", 7, 1);
	check_memparse(test, "7D", 7, 1);
	/* letters adjacent to valid suffixes in ASCII */
	check_memparse(test, "7J", 7, 1);
	check_memparse(test, "7L", 7, 1);
	check_memparse(test, "7N", 7, 1);
	check_memparse(test, "7O", 7, 1);
	check_memparse(test, "7Q", 7, 1);
	check_memparse(test, "7S", 7, 1);
	check_memparse(test, "7U", 7, 1);
	check_memparse(test, "7H", 7, 1);
}

static void memparse_trailing_text(struct kunit *test)
{
	check_memparse(test, "1@2", 1, 1);
	check_memparse(test, "16M@0x1000", 16ULL << 20, 3);
	check_memparse(test, "32K,foo", 32ULL << 10, 3);
	check_memparse(test, "4G:bar", 4ULL << 30, 2);
	check_memparse(test, "100 200", 100, 3);
	check_memparse(test, "1-2", 1, 1);
	check_memparse(test, "0x10,", 16, 4);
	check_memparse(test, "1K\n", 1ULL << 10, 2);
}

static void memparse_no_digits(struct kunit *test)
{
	check_memparse(test, "", 0, 0);
	check_memparse(test, "K", 0, 1);
	check_memparse(test, "M", 0, 1);
	check_memparse(test, "g", 0, 1);
	check_memparse(test, "abc", 0, 0);
	check_memparse(test, " 1", 0, 0);
	check_memparse(test, "-1", 0, 0);
	check_memparse(test, "+1", 0, 0);
	check_memparse(test, "x", 0, 0);
	check_memparse(test, "@", 0, 0);
}

static void memparse_null_retptr(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, memparse("0", NULL), 0ULL);
	KUNIT_EXPECT_EQ(test, memparse("42", NULL), 42ULL);
	KUNIT_EXPECT_EQ(test, memparse("3M", NULL), 3ULL << 20);
	KUNIT_EXPECT_EQ(test, memparse("0x1G", NULL), 1ULL << 30);
	KUNIT_EXPECT_EQ(test, memparse("", NULL), 0ULL);
}

/* retptr must point into the original buffer, usable for chained parsing. */
static void memparse_chained(struct kunit *test)
{
	char buf[] = "1M,2K,3";
	char *p = buf;

	KUNIT_EXPECT_EQ(test, memparse(p, &p), 1ULL << 20);
	KUNIT_EXPECT_EQ(test, *p, ',');
	p++;
	KUNIT_EXPECT_EQ(test, memparse(p, &p), 2ULL << 10);
	KUNIT_EXPECT_EQ(test, *p, ',');
	p++;
	KUNIT_EXPECT_EQ(test, memparse(p, &p), 3ULL);
	KUNIT_EXPECT_EQ(test, *p, '\0');
	KUNIT_EXPECT_PTR_EQ(test, p, buf + sizeof(buf) - 1);
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(memparse_plain_decimal),
	KUNIT_CASE(memparse_hex_and_octal),
	KUNIT_CASE(memparse_suffix_k),
	KUNIT_CASE(memparse_suffix_m),
	KUNIT_CASE(memparse_suffix_g),
	KUNIT_CASE(memparse_suffix_t),
	KUNIT_CASE(memparse_suffix_p),
	KUNIT_CASE(memparse_suffix_e),
	KUNIT_CASE(memparse_suffix_ladder),
	KUNIT_CASE(memparse_overflow),
	KUNIT_CASE(memparse_single_suffix_only),
	KUNIT_CASE(memparse_unknown_suffix),
	KUNIT_CASE(memparse_trailing_text),
	KUNIT_CASE(memparse_no_digits),
	KUNIT_CASE(memparse_null_retptr),
	KUNIT_CASE(memparse_chained),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};

kunit_test_suite(agent_test_suite);

