/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Test suite for __siphash_aligned() in lib/siphash.c.
 *
 * __siphash_aligned() is only built when the architecture lacks
 * CONFIG_HAVE_EFFICIENT_UNALIGNED_ACCESS (the header otherwise routes all
 * callers to __siphash_unaligned()). The suite is therefore compiled out
 * on such architectures so the build never references a missing symbol.
 */

#include <kunit/test.h>
#include <linux/siphash.h>
#include <linux/kernel.h>
#include <linux/string.h>
#include <linux/random.h>

#ifndef CONFIG_HAVE_EFFICIENT_UNALIGNED_ACCESS

/*
 * Reference SipHash-2-4 vectors from https://github.com/veorq/SipHash
 * (same as used by lib/siphash_kunit.c): key = 00 01 .. 0f, message of
 * length i is the bytes 00 01 .. (i-1).
 */
static const siphash_key_t agent_ref_key =
	{{ 0x0706050403020100ULL, 0x0f0e0d0c0b0a0908ULL }};

static const u64 agent_ref_vectors[64] = {
	0x726fdb47dd0e0e31ULL, 0x74f839c593dc67fdULL, 0x0d6c8009d9a94f5aULL,
	0x85676696d7fb7e2dULL, 0xcf2794e0277187b7ULL, 0x18765564cd99a68dULL,
	0xcbc9466e58fee3ceULL, 0xab0200f58b01d137ULL, 0x93f5f5799a932462ULL,
	0x9e0082df0ba9e4b0ULL, 0x7a5dbbc594ddb9f3ULL, 0xf4b32f46226bada7ULL,
	0x751e8fbc860ee5fbULL, 0x14ea5627c0843d90ULL, 0xf723ca908e7af2eeULL,
	0xa129ca6149be45e5ULL, 0x3f2acc7f57c29bdbULL, 0x699ae9f52cbe4794ULL,
	0x4bc1b3f0968dd39cULL, 0xbb6dc91da77961bdULL, 0xbed65cf21aa2ee98ULL,
	0xd0f2cbb02e3b67c7ULL, 0x93536795e3a33e88ULL, 0xa80c038ccd5ccec8ULL,
	0xb8ad50c6f649af94ULL, 0xbce192de8a85b8eaULL, 0x17d835b85bbb15f3ULL,
	0x2f2e6163076bcfadULL, 0xde4daaaca71dc9a5ULL, 0xa6a2506687956571ULL,
	0xad87a3535c49ef28ULL, 0x32d892fad841c342ULL, 0x7127512f72f27cceULL,
	0xa7f32346f95978e3ULL, 0x12e0b01abb051238ULL, 0x15e034d40fa197aeULL,
	0x314dffbe0815a3b4ULL, 0x027990f029623981ULL, 0xcadcd4e59ef40c4dULL,
	0x9abfd8766a33735cULL, 0x0e3ea96b5304a7d0ULL, 0xad0c42d6fc585992ULL,
	0x187306c89bc215a9ULL, 0xd4a60abcf3792b95ULL, 0xf935451de4f21df2ULL,
	0xa9538f0419755787ULL, 0xdb9acddff56ca510ULL, 0xd06c98cd5c0975ebULL,
	0xe612a3cb9ecba951ULL, 0xc766e62cfcadaf96ULL, 0xee64435a9752fe72ULL,
	0xa192d576b245165aULL, 0x0a8787bf8ecb74b2ULL, 0x81b3e73d20b49b6fULL,
	0x7fa8220ba3b2eceaULL, 0x245731c13ca42499ULL, 0xb78dbfaf3a8d83bdULL,
	0xea1ad565322a1a0bULL, 0x60e61c23a3795013ULL, 0x6606d7e446282b93ULL,
	0x6ca4ecb15c5f91e1ULL, 0x9f626da15c9625f3ULL, 0xe51b38608ef25f57ULL,
	0x958a324ceb064572ULL
};

/* An aligned, oversized buffer so every test can place poison after data. */
#define AGENT_BUF_SIZE 128

struct agent_ctx {
	u8 buf[AGENT_BUF_SIZE] __aligned(SIPHASH_ALIGNMENT);
};

static int agent_test_init(struct kunit *test)
{
	struct agent_ctx *ctx = kunit_kzalloc(test, sizeof(*ctx), GFP_KERNEL);

	KUNIT_ASSERT_NOT_ERR_OR_NULL(test, ctx);
	test->priv = ctx;
	return 0;
}

static void fill_seq(u8 *buf, size_t len)
{
	size_t i;

	for (i = 0; i < len; ++i)
		buf[i] = (u8)i;
}

/*
 * Known-answer test: every length 0..63 against the official vectors.
 * The tail of the buffer is poisoned with 0xff so that any over-read of
 * bytes beyond @len (e.g. an off-by-one in the `left` switch) changes
 * the result and the check fails.
 */
static void agent_siphash_known_answers(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	size_t len;

	for (len = 0; len < ARRAY_SIZE(agent_ref_vectors); ++len) {
		memset(ctx->buf, 0xff, AGENT_BUF_SIZE);
		fill_seq(ctx->buf, len);
		KUNIT_EXPECT_EQ_MSG(test,
				    __siphash_aligned(ctx->buf, len, &agent_ref_key),
				    agent_ref_vectors[len],
				    "known-answer mismatch at len=%zu", len);
	}
}

/* len == 0 must hash nothing but still fold the length into b. */
static void agent_siphash_empty(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	const siphash_key_t zero_key = {{ 0, 0 }};
	u64 a, b;

	memset(ctx->buf, 0xff, AGENT_BUF_SIZE);
	KUNIT_EXPECT_EQ(test, __siphash_aligned(ctx->buf, 0, &agent_ref_key),
			agent_ref_vectors[0]);

	/* Contents of the buffer must be irrelevant when len == 0. */
	memset(ctx->buf, 0x00, AGENT_BUF_SIZE);
	a = __siphash_aligned(ctx->buf, 0, &agent_ref_key);
	memset(ctx->buf, 0xa5, AGENT_BUF_SIZE);
	b = __siphash_aligned(ctx->buf, 0, &agent_ref_key);
	KUNIT_EXPECT_EQ(test, a, b);
	KUNIT_EXPECT_EQ(test, a, agent_ref_vectors[0]);

	/* Empty input with an all-zero key is still a defined, nonzero PRF. */
	a = __siphash_aligned(ctx->buf, 0, &zero_key);
	KUNIT_EXPECT_NE(test, a, 0ULL);
	KUNIT_EXPECT_NE(test, a, agent_ref_vectors[0]);
}

/*
 * Boundaries around each 8-byte block: lengths 7,8,9, 15,16,17, 23,24,25,
 * ... must match the reference vectors and must all differ from each
 * other (an off-by-one in the `end` computation would merge neighbours).
 */
static void agent_siphash_block_boundaries(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	size_t blk;

	for (blk = 8; blk <= 56; blk += 8) {
		u64 h_before, h_at, h_after;

		memset(ctx->buf, 0xff, AGENT_BUF_SIZE);
		fill_seq(ctx->buf, 64);

		h_before = __siphash_aligned(ctx->buf, blk - 1, &agent_ref_key);
		h_at = __siphash_aligned(ctx->buf, blk, &agent_ref_key);
		h_after = __siphash_aligned(ctx->buf, blk + 1, &agent_ref_key);

		KUNIT_EXPECT_EQ_MSG(test, h_before, agent_ref_vectors[blk - 1],
				    "len=%zu", blk - 1);
		KUNIT_EXPECT_EQ_MSG(test, h_at, agent_ref_vectors[blk],
				    "len=%zu", blk);
		KUNIT_EXPECT_EQ_MSG(test, h_after, agent_ref_vectors[blk + 1],
				    "len=%zu", blk + 1);
		KUNIT_EXPECT_NE(test, h_before, h_at);
		KUNIT_EXPECT_NE(test, h_at, h_after);
		KUNIT_EXPECT_NE(test, h_before, h_after);
	}
}

/*
 * Every partial-tail length (left = 1..7) must consume exactly `left`
 * bytes: flipping the last in-range byte changes the hash, flipping the
 * first out-of-range byte does not.
 */
static void agent_siphash_tail_bytes(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	size_t base, left;

	for (base = 0; base <= 16; base += 8) {
		for (left = 1; left < 8; ++left) {
			size_t len = base + left;
			u64 ref, h;

			memset(ctx->buf, 0, AGENT_BUF_SIZE);
			fill_seq(ctx->buf, len);
			ref = __siphash_aligned(ctx->buf, len, &agent_ref_key);
			KUNIT_EXPECT_EQ_MSG(test, ref, agent_ref_vectors[len],
					    "len=%zu", len);

			/* Byte just past the end must be ignored. */
			ctx->buf[len] ^= 0x5a;
			h = __siphash_aligned(ctx->buf, len, &agent_ref_key);
			KUNIT_EXPECT_EQ_MSG(test, h, ref,
					    "byte past end affected hash, len=%zu",
					    len);
			ctx->buf[len] ^= 0x5a;

			/* Last in-range byte must be included. */
			ctx->buf[len - 1] ^= 0x5a;
			h = __siphash_aligned(ctx->buf, len, &agent_ref_key);
			KUNIT_EXPECT_NE_MSG(test, h, ref,
					    "last byte ignored, len=%zu", len);
			ctx->buf[len - 1] ^= 0x5a;

			/* First byte must be included too. */
			ctx->buf[0] ^= 0x5a;
			h = __siphash_aligned(ctx->buf, len, &agent_ref_key);
			KUNIT_EXPECT_NE_MSG(test, h, ref,
					    "first byte ignored, len=%zu", len);
			ctx->buf[0] ^= 0x5a;
		}
	}
}

/*
 * Each tail byte position must land in its own bit lane of `b`: for a
 * given left, two messages differing in only tail byte i must hash
 * differently for every i < left, and the per-position hashes must be
 * pairwise distinct (catches a wrong shift such as <<40 vs <<48).
 */
static void agent_siphash_tail_lanes(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	u64 hs[8];
	size_t left, i, j;

	for (left = 1; left < 8; ++left) {
		size_t len = 8 + left;

		for (i = 0; i < left; ++i) {
			memset(ctx->buf, 0, AGENT_BUF_SIZE);
			ctx->buf[8 + i] = 0x01;
			hs[i] = __siphash_aligned(ctx->buf, len, &agent_ref_key);
		}
		for (i = 0; i < left; ++i)
			for (j = i + 1; j < left; ++j)
				KUNIT_EXPECT_NE_MSG(test, hs[i], hs[j],
						    "left=%zu lanes %zu and %zu collide",
						    left, i, j);
	}
}

/* Aligned and unaligned implementations must agree for all lengths. */
static void agent_siphash_matches_unaligned(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	siphash_key_t key;
	size_t len;

	get_random_bytes(&key, sizeof(key));
	get_random_bytes(ctx->buf, AGENT_BUF_SIZE);

	for (len = 0; len <= 100; ++len)
		KUNIT_EXPECT_EQ_MSG(test,
				    __siphash_aligned(ctx->buf, len, &key),
				    __siphash_unaligned(ctx->buf, len, &key),
				    "len=%zu", len);
}

/* Must agree with the fixed-width fast paths siphash_{1,2,3,4}u64/1u32. */
static void agent_siphash_matches_fixed_width(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	siphash_key_t key;
	__le64 w[4];
	__le32 w32;
	u64 a, b, c, d;

	get_random_bytes(&key, sizeof(key));
	get_random_bytes(w, sizeof(w));
	get_random_bytes(&w32, sizeof(w32));
	a = le64_to_cpu(w[0]);
	b = le64_to_cpu(w[1]);
	c = le64_to_cpu(w[2]);
	d = le64_to_cpu(w[3]);

	memcpy(ctx->buf, w, sizeof(w));
	KUNIT_EXPECT_EQ(test, __siphash_aligned(ctx->buf, 8, &key),
			siphash_1u64(a, &key));
	KUNIT_EXPECT_EQ(test, __siphash_aligned(ctx->buf, 16, &key),
			siphash_2u64(a, b, &key));
	KUNIT_EXPECT_EQ(test, __siphash_aligned(ctx->buf, 24, &key),
			siphash_3u64(a, b, c, &key));
	KUNIT_EXPECT_EQ(test, __siphash_aligned(ctx->buf, 32, &key),
			siphash_4u64(a, b, c, d, &key));

	memcpy(ctx->buf, &w32, sizeof(w32));
	KUNIT_EXPECT_EQ(test, __siphash_aligned(ctx->buf, 4, &key),
			siphash_1u32(le32_to_cpu(w32), &key));
}

/*
 * Length must be part of the hash: a message padded with zeros to a
 * longer length must hash differently from the shorter one.
 */
static void agent_siphash_length_sensitivity(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	u64 hs[32];
	size_t i, j;

	memset(ctx->buf, 0, AGENT_BUF_SIZE);
	for (i = 0; i < ARRAY_SIZE(hs); ++i)
		hs[i] = __siphash_aligned(ctx->buf, i, &agent_ref_key);
	for (i = 0; i < ARRAY_SIZE(hs); ++i)
		for (j = i + 1; j < ARRAY_SIZE(hs); ++j)
			KUNIT_EXPECT_NE_MSG(test, hs[i], hs[j],
					    "all-zero messages of len %zu and %zu collide",
					    i, j);
}

/* Both key halves must influence the result, independently. */
static void agent_siphash_key_sensitivity(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	siphash_key_t k0 = {{ 0, 0 }};
	siphash_key_t k1 = {{ 1, 0 }};
	siphash_key_t k2 = {{ 0, 1 }};
	siphash_key_t k3 = {{ 1ULL << 63, 0 }};
	siphash_key_t kswap = {{ agent_ref_key.key[1], agent_ref_key.key[0] }};
	size_t len;

	fill_seq(ctx->buf, 64);
	for (len = 0; len <= 17; ++len) {
		u64 h0 = __siphash_aligned(ctx->buf, len, &k0);
		u64 h1 = __siphash_aligned(ctx->buf, len, &k1);
		u64 h2 = __siphash_aligned(ctx->buf, len, &k2);
		u64 h3 = __siphash_aligned(ctx->buf, len, &k3);
		u64 hr = __siphash_aligned(ctx->buf, len, &agent_ref_key);
		u64 hswap = __siphash_aligned(ctx->buf, len, &kswap);

		KUNIT_EXPECT_NE_MSG(test, h0, h1, "key[0] ignored, len=%zu", len);
		KUNIT_EXPECT_NE_MSG(test, h0, h2, "key[1] ignored, len=%zu", len);
		KUNIT_EXPECT_NE_MSG(test, h1, h2, "key halves conflated, len=%zu", len);
		KUNIT_EXPECT_NE_MSG(test, h0, h3, "key[0] msb ignored, len=%zu", len);
		KUNIT_EXPECT_NE_MSG(test, hr, hswap, "key order ignored, len=%zu", len);
	}
}

/* Determinism and const-correctness of input: same call, same answer. */
static void agent_siphash_deterministic(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	u8 snapshot[AGENT_BUF_SIZE];
	siphash_key_t key, key_copy;
	size_t len;

	get_random_bytes(&key, sizeof(key));
	get_random_bytes(ctx->buf, AGENT_BUF_SIZE);
	memcpy(snapshot, ctx->buf, AGENT_BUF_SIZE);
	key_copy = key;

	for (len = 0; len < 64; len += 5) {
		u64 h1 = __siphash_aligned(ctx->buf, len, &key);
		u64 h2 = __siphash_aligned(ctx->buf, len, &key);

		KUNIT_EXPECT_EQ_MSG(test, h1, h2, "len=%zu", len);
	}
	/* Neither the data nor the key may be modified. */
	KUNIT_EXPECT_MEMEQ(test, ctx->buf, snapshot, AGENT_BUF_SIZE);
	KUNIT_EXPECT_MEMEQ(test, &key, &key_copy, sizeof(key));
}

/*
 * Each full 8-byte block must be absorbed: flipping any single byte of
 * a multi-block message must change the hash (every byte position
 * 0..len-1 for len = 24).
 */
static void agent_siphash_every_byte_matters(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	const size_t len = 24;
	u64 ref;
	size_t i;

	fill_seq(ctx->buf, 64);
	ref = __siphash_aligned(ctx->buf, len, &agent_ref_key);
	KUNIT_EXPECT_EQ(test, ref, agent_ref_vectors[len]);

	for (i = 0; i < len; ++i) {
		u64 h;

		ctx->buf[i] ^= 0x80;
		h = __siphash_aligned(ctx->buf, len, &agent_ref_key);
		ctx->buf[i] ^= 0x80;
		KUNIT_EXPECT_NE_MSG(test, h, ref, "byte %zu ignored", i);
	}
	/* Sanity: restored buffer hashes back to the reference. */
	KUNIT_EXPECT_EQ(test, __siphash_aligned(ctx->buf, len, &agent_ref_key),
			ref);
}

/* Large inputs: longer than any reference vector, exact and off-by-one. */
static void agent_siphash_long_input(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	siphash_key_t key;
	size_t len;

	get_random_bytes(&key, sizeof(key));
	get_random_bytes(ctx->buf, AGENT_BUF_SIZE);

	for (len = 120; len <= AGENT_BUF_SIZE; ++len) {
		u64 h = __siphash_aligned(ctx->buf, len, &key);

		KUNIT_EXPECT_EQ_MSG(test, h, __siphash_unaligned(ctx->buf, len, &key),
				    "len=%zu", len);
		if (len > 120)
			KUNIT_EXPECT_NE_MSG(test, h,
					    __siphash_aligned(ctx->buf, len - 1, &key),
					    "len %zu and %zu collide", len, len - 1);
	}
}

/*
 * Messages that differ only in the trailing block's byte ORDER must
 * differ (checks the little-endian load, not a byte-sum).
 */
static void agent_siphash_byte_order(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	u64 h1, h2;
	size_t len;

	for (len = 2; len <= 16; ++len) {
		memset(ctx->buf, 0, AGENT_BUF_SIZE);
		ctx->buf[0] = 0x11;
		ctx->buf[len - 1] = 0x22;
		h1 = __siphash_aligned(ctx->buf, len, &agent_ref_key);
		ctx->buf[0] = 0x22;
		ctx->buf[len - 1] = 0x11;
		h2 = __siphash_aligned(ctx->buf, len, &agent_ref_key);
		KUNIT_EXPECT_NE_MSG(test, h1, h2, "len=%zu", len);
	}
}

static struct kunit_case agent_test_cases[] = {
