/* Buffer type guaranteeing the alignment the function requires. */
struct agent_buf {
	u8 b[256] __aligned(HSIPHASH_ALIGNMENT);
};

static void agent_fill_seq(u8 *buf, size_t n)
{
	size_t i;

	for (i = 0; i < n; ++i)
		buf[i] = (u8)i;
}

/* Every official vector, lengths 0..63, must match exactly. */
static void agent_known_vectors(struct kunit *test)
{
	struct agent_buf in;
	size_t i;

	agent_fill_seq(in.b, 64);
	for (i = 0; i < 64; ++i)
		KUNIT_EXPECT_EQ_MSG(test, __hsiphash_aligned(in.b, i, &agent_key),
				    agent_vectors[i], "len %zu", i);
}

/* Empty input: no block processed, only the length byte matters. */
static void agent_empty_input(struct kunit *test)
{
	struct agent_buf in;

	memset(in.b, 0xa5, sizeof(in.b));
	KUNIT_EXPECT_EQ(test, __hsiphash_aligned(in.b, 0, &agent_key),
			agent_vectors[0]);
	/* Content must not matter when len == 0. */
	memset(in.b, 0x00, sizeof(in.b));
	KUNIT_EXPECT_EQ(test, __hsiphash_aligned(in.b, 0, &agent_key),
			agent_vectors[0]);
	/* But the key still must. */
	KUNIT_EXPECT_NE(test, __hsiphash_aligned(in.b, 0, &agent_key),
			__hsiphash_aligned(in.b, 0, &agent_zero_key));
}

/* Each tail length 1..WORD-1 must consume exactly 'left' bytes. */
static void agent_tail_bytes_exact(struct kunit *test)
{
	struct agent_buf a, b;
	size_t base, left, k;

	for (base = 0; base <= 2 * AGENT_WORD; base += AGENT_WORD) {
		for (left = 1; left < AGENT_WORD; ++left) {
			size_t len = base + left;

			agent_fill_seq(a.b, sizeof(a.b));
			memcpy(b.b, a.b, sizeof(a.b));
			/* Byte right after the end must NOT influence hash. */
			b.b[len] ^= 0xff;
			KUNIT_EXPECT_EQ_MSG(test,
					    __hsiphash_aligned(a.b, len, &agent_key),
					    __hsiphash_aligned(b.b, len, &agent_key),
					    "len %zu: byte past end leaked in", len);
			/* Every byte inside the tail MUST influence hash. */
			for (k = base; k < len; ++k) {
				memcpy(b.b, a.b, sizeof(a.b));
				b.b[k] ^= 0x01;
				KUNIT_EXPECT_NE_MSG(test,
						    __hsiphash_aligned(a.b, len, &agent_key),
						    __hsiphash_aligned(b.b, len, &agent_key),
						    "len %zu: byte %zu ignored", len, k);
			}
		}
	}
}

/* Full-word lengths must consume all bytes and nothing more. */
static void agent_block_boundaries(struct kunit *test)
{
	struct agent_buf a, b;
	size_t len, k;

	for (len = AGENT_WORD; len <= 4 * AGENT_WORD; len += AGENT_WORD) {
		agent_fill_seq(a.b, sizeof(a.b));
		memcpy(b.b, a.b, sizeof(a.b));
		b.b[len] ^= 0xff;
		KUNIT_EXPECT_EQ_MSG(test,
				    __hsiphash_aligned(a.b, len, &agent_key),
				    __hsiphash_aligned(b.b, len, &agent_key),
				    "len %zu: byte past end leaked in", len);
		for (k = 0; k < len; ++k) {
			memcpy(b.b, a.b, sizeof(a.b));
			b.b[k] ^= 0x80;
			KUNIT_EXPECT_NE_MSG(test,
					    __hsiphash_aligned(a.b, len, &agent_key),
					    __hsiphash_aligned(b.b, len, &agent_key),
					    "len %zu: byte %zu ignored", len, k);
		}
	}
}

/* Same bytes, different lengths, must give different hashes. */
static void agent_length_is_hashed(struct kunit *test)
{
	struct agent_buf in;
	size_t i, j;
	u32 h[65];

	memset(in.b, 0, sizeof(in.b));
	for (i = 0; i <= 64; ++i)
		h[i] = __hsiphash_aligned(in.b, i, &agent_key);
	for (i = 0; i <= 64; ++i)
		for (j = i + 1; j <= 64; ++j)
			KUNIT_EXPECT_NE_MSG(test, h[i], h[j],
					    "zero buf len %zu == len %zu", i, j);
}

/* Aligned and unaligned implementations must agree on every length. */
static void agent_matches_unaligned(struct kunit *test)
{
	struct agent_buf in;
	size_t i;

	agent_fill_seq(in.b, sizeof(in.b));
	for (i = 0; i <= 128; ++i)
		KUNIT_EXPECT_EQ_MSG(test, __hsiphash_aligned(in.b, i, &agent_key),
				    __hsiphash_unaligned(in.b, i, &agent_key),
				    "len %zu", i);
	memset(in.b, 0xff, sizeof(in.b));
	for (i = 0; i <= 128; ++i)
		KUNIT_EXPECT_EQ_MSG(test, __hsiphash_aligned(in.b, i, &agent_key),
				    __hsiphash_unaligned(in.b, i, &agent_key),
				    "0xff len %zu", i);
}

/* Must agree with the fixed-width helpers for 4/8/12/16 byte inputs. */
static void agent_matches_fixed_helpers(struct kunit *test)
{
	struct agent_buf in;
	u32 w[4];

	agent_fill_seq(in.b, 16);
	w[0] = 0x03020100U;
	w[1] = 0x07060504U;
	w[2] = 0x0b0a0908U;
	w[3] = 0x0f0e0d0cU;

	KUNIT_EXPECT_EQ(test, __hsiphash_aligned(in.b, 4, &agent_key),
			hsiphash_1u32(w[0], &agent_key));
	KUNIT_EXPECT_EQ(test, __hsiphash_aligned(in.b, 8, &agent_key),
			hsiphash_2u32(w[0], w[1], &agent_key));
	KUNIT_EXPECT_EQ(test, __hsiphash_aligned(in.b, 12, &agent_key),
			hsiphash_3u32(w[0], w[1], w[2], &agent_key));
	KUNIT_EXPECT_EQ(test, __hsiphash_aligned(in.b, 16, &agent_key),
			hsiphash_4u32(w[0], w[1], w[2], w[3], &agent_key));

	/* Also with a different key and data pattern. */
	memset(in.b, 0xc3, 16);
	KUNIT_EXPECT_EQ(test, __hsiphash_aligned(in.b, 4, &agent_zero_key),
			hsiphash_1u32(0xc3c3c3c3U, &agent_zero_key));
	KUNIT_EXPECT_EQ(test, __hsiphash_aligned(in.b, 16, &agent_zero_key),
			hsiphash_4u32(0xc3c3c3c3U, 0xc3c3c3c3U, 0xc3c3c3c3U,
				      0xc3c3c3c3U, &agent_zero_key));
}

/* Both key halves matter and their order matters. */
static void agent_key_sensitivity(struct kunit *test)
{
	struct agent_buf in;
	hsiphash_key_t k;
	size_t len;

	agent_fill_seq(in.b, sizeof(in.b));
	for (len = 0; len <= 2 * AGENT_WORD + 1; ++len) {
		u32 ref = __hsiphash_aligned(in.b, len, &agent_key);

		KUNIT_EXPECT_NE_MSG(test, ref,
				    __hsiphash_aligned(in.b, len, &agent_zero_key),
				    "len %zu zero key", len);
		KUNIT_EXPECT_NE_MSG(test, ref,
				    __hsiphash_aligned(in.b, len, &agent_key_swapped),
				    "len %zu swapped key", len);
		k = agent_key;
		k.key[0] ^= 1;
		KUNIT_EXPECT_NE_MSG(test, ref, __hsiphash_aligned(in.b, len, &k),
				    "len %zu key[0] bit flip", len);
		k = agent_key;
		k.key[1] ^= 1;
		KUNIT_EXPECT_NE_MSG(test, ref, __hsiphash_aligned(in.b, len, &k),
				    "len %zu key[1] bit flip", len);
	}
}

/* Determinism: repeated calls and separate equal buffers give same value. */
static void agent_deterministic(struct kunit *test)
{
	struct agent_buf a, b;
	size_t len;

	agent_fill_seq(a.b, sizeof(a.b));
	memcpy(b.b, a.b, sizeof(b.b));
	for (len = 0; len <= 3 * AGENT_WORD + 3; ++len) {
		u32 h1 = __hsiphash_aligned(a.b, len, &agent_key);
		u32 h2 = __hsiphash_aligned(a.b, len, &agent_key);
		u32 h3 = __hsiphash_aligned(b.b, len, &agent_key);

		KUNIT_EXPECT_EQ_MSG(test, h1, h2, "len %zu", len);
		KUNIT_EXPECT_EQ_MSG(test, h1, h3, "len %zu", len);
	}
}

/* Hashing a mid-buffer aligned window must only depend on the window. */
static void agent_offset_window(struct kunit *test)
{
	struct agent_buf a, b;
	size_t len;

	agent_fill_seq(a.b, sizeof(a.b));
	for (len = 0; len <= 2 * AGENT_WORD + 3; ++len) {
		u32 ref = __hsiphash_aligned(a.b, len, &agent_key);

		/* Same bytes placed at a different aligned offset. */
		memset(b.b, 0xee, sizeof(b.b));
		memcpy(b.b + 2 * AGENT_WORD, a.b, len);
		KUNIT_EXPECT_EQ_MSG(test, ref,
				    __hsiphash_aligned(b.b + 2 * AGENT_WORD, len,
						       &agent_key),
				    "len %zu", len);
	}
}

/* Bit-flip in any position of a long multi-block message changes output. */
static void agent_long_message_avalanche(struct kunit *test)
{
	struct agent_buf a, b;
	const size_t len = 8 * AGENT_WORD + 5;
	size_t k;
	u32 ref;

	agent_fill_seq(a.b, sizeof(a.b));
	ref = __hsiphash_aligned(a.b, len, &agent_key);
	for (k = 0; k < len; ++k) {
		memcpy(b.b, a.b, sizeof(a.b));
		b.b[k] ^= 0x10;
		KUNIT_EXPECT_NE_MSG(test, ref,
				    __hsiphash_aligned(b.b, len, &agent_key),
				    "byte %zu ignored", k);
	}
	/* Bytes after end are irrelevant. */
	memcpy(b.b, a.b, sizeof(a.b));
	b.b[len] = ~b.b[len];
	b.b[len + 1] = ~b.b[len + 1];
	KUNIT_EXPECT_EQ(test, ref, __hsiphash_aligned(b.b, len, &agent_key));
}

/* Larger lengths: 64..200, vs unaligned implementation and no collisions
 * across lengths for constant data.
 */
static void agent_large_lengths(struct kunit *test)
{
	struct agent_buf in;
	size_t i, j;
	u32 h[137];

	memset(in.b, 0x5a, sizeof(in.b));
	for (i = 64; i <= 200; ++i) {
		h[i - 64] = __hsiphash_aligned(in.b, i, &agent_key);
		KUNIT_EXPECT_EQ_MSG(test, h[i - 64],
				    __hsiphash_unaligned(in.b, i, &agent_key),
				    "len %zu", i);
	}
	for (i = 0; i < 137; ++i)
		for (j = i + 1; j < 137; ++j)
			KUNIT_EXPECT_NE_MSG(test, h[i], h[j],
					    "len %zu == len %zu", i + 64, j + 64);
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(agent_known_vectors),
	KUNIT_CASE(agent_empty_input),
	KUNIT_CASE(agent_tail_bytes_exact),
	KUNIT_CASE(agent_block_boundaries),
	KUNIT_CASE(agent_length_is_hashed),
	KUNIT_CASE(agent_matches_unaligned),
	KUNIT_CASE(agent_matches_fixed_helpers),
	KUNIT_CASE(agent_key_sensitivity),
	KUNIT_CASE(agent_deterministic),
	KUNIT_CASE(agent_offset_window),
	KUNIT_CASE(agent_long_message_avalanche),
	KUNIT_CASE(agent_large_lengths),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};

kunit_test_suite(agent_test_suite);

